package java.util.concurrent;
public class FTFY_FutureTask<V> implements java.util.concurrent.FutureTask<V> {
    /* Fake field which will taint the whole object by taint lookup */
    public Object result;
    public FTFY_FutureTask(java.util.concurrent.Callable<V> callable) {
        result = callable.call();
    }
}

public class java.util.concurrent.FTFY_ForkJoinPool_execute extends java.util.concurrent.ForkJoinPool {
    public void execute(java.util.concurrent.ForkJoinTask<?> task) {
        public Object result;
        if (task instanceof java.util.concurrent.RecursiveAction) {
            result = ((java.util.concurrent.RecursiveAction) task).compute();
        }
        else if (task instanceof java.util.concurrent.RecursiveTask) {
            result = ((java.util.concurrent.RecursiveTask) task).compute();
        }
        else if (task instanceof java.util.concurrent.CountedCompleter) {
            result = ((java.util.concurrent.CountedCompleter) task).compute();
        }
        else {
            result = task.getRawResult();
        }
        task = (java.util.concurrent.ForkJoinTask) result;
    }
}

