        //
// This function queries MetaTable for a return type of a function fName defined in class cName.
//
function queryMetaTableForFunctionReturnType(cName, fName) {
  var metatable = getMetaTable();
  var allClasses = metatable.getAllClasses();

  for each (var c in allClasses.toArray()) {
    var allFunctions = c.getMemberFunctions();
    for each (var f in allFunctions) {
      if (cName == c.getCanonicalName() && fName == f.getSimpleName()) {
        return (null == f.getReturnType().getClassSymbol()) ? "" : String(f.getReturnType().getClassSymbol().getCanonicalName());
      }
    }
  }
  return "";
}

function logWrapper(value) {
   log(value);
}

    //
