      if(typeof nameTable.getMethodReturnType != 'undefined') {
        var returnTypes = nameTable.getMethodReturnType(cName, fName, "java");
        if (null == returnTypes || 0 == returnTypes.length || 1 < returnTypes.length) {
          return "";
        }
        else {
//alert("CLASS IS: " + cName);
//alert("FUNCTION IS: " + fName);
//alert("RETURN TYPE IS: " + returnTypes[0]);
