// Function to split fully qualified classname into namespace (ns) and className (clsName).
function splitFullyQualifiedClsName (fullyQualifiedClsName) {
  var dotIndex = String(fullyQualifiedClsName).lastIndexOf(".");
  var returnObj = new Object();
  returnObj.ns = String(fullyQualifiedClsName).substring(0, dotIndex);
  returnObj.clsName = String(fullyQualifiedClsName).substr(dotIndex+1);
  return returnObj;
}



    // helper for isSubClass below
    function isSubClassHelper(subclass, targetName) {
        var directSupers = subclass.getSuperClasses();
        var found = false;

        if (directSupers == null || directSupers.length == 0)  {
            return false;
        }

        for each (var sup in directSupers) {
            var dsFullName = sup.getPackageName() ? sup.getPackageName() + "." + sup.getName()
                                                  : sup.getName();
            if (targetName == dsFullName) {
                return true;
            }
            found = found || isSubClassHelper(sup, targetName);
        }

        return found;
    }

    //
    // Returns a boolean based on whether subName is a descendent class of superName
    // subName and superName are both strings expressed as fully qualified class names, e.g., "java.util.List"
    //
    function isSubClass(subName, superName) {
        var clsIndex = subName.lastIndexOf(".");

        if (clsIndex == -1) {
            return false;
        }

        var subPkgName = subName.substring(0, clsIndex);
        var subClsName = subName.substring(clsIndex+1);
        var subType = nameTable.getClassByName(subPkgName, subClsName, "java");

        if (!subType || subType.getName() == "[UnknownType]") {
            return false;
        }

        return isSubClassHelper(subType, superName);
    }

var defaultNamespace = new Namespace("");
var axisServiceCount = 0;
if (program.axisService == null)
    program.axisService = new Array();

for each (var servicesXMLFile in program.xml) {

    if (null == servicesXMLFile.name() || (null == servicesXMLFile.name().localName.match("service") && null == servicesXMLFile.name().localName.match("serviceGroup"))) {
    continue;
    }

    var currentServiceElement = 0;
    var targetNode = null;

    if (servicesXMLFile.name().localName.match("serviceGroup")) {
    // Multiple services being described
    targetNode = servicesXMLFile..defaultNamespace::["service"];

    }
    else if (servicesXMLFile.name().localName.match("service")) {
    // Only one service being described
    targetNode = servicesXMLFile;
    }

    for each (var serviceDescriptor in targetNode) {

    var thisAxisService = new Object();
    thisAxisService.className = "";
    thisAxisService.namespaceName = "";
    thisAxisService.functionName = "";
    thisAxisService.modifier = "";

    // Extract namespace, class, and method that contains exposed web service
    var serviceClassCount = serviceDescriptor..defaultNamespace::["parameter"].(@name == "ServiceClass").length();
    if (serviceClassCount != 1) {
        continue;
    }

    thisAxisService.className = String(serviceDescriptor..defaultNamespace::["parameter"].(@name == "ServiceClass"));
    if (thisAxisService.className == null) {
        continue;
    }

    var dotIndex = thisAxisService.className.lastIndexOf(".");

    if (dotIndex == -1) {
      thisAxisService.namespaceName = "";
    }
    else {
        thisAxisService.namespaceName = thisAxisService.className.substring(0, dotIndex);
        thisAxisService.className = thisAxisService.className.substr(dotIndex + 1);
    }

    // make sure we're dealing with valid Java package names and class names
    if (false == isValidJavaPackageName(thisAxisService.namespaceName) || false == isValidJavaIdentifier(thisAxisService.className)) {
      continue;
    }

    // User has not specified individual methods to expose, so expose all public methods
    if (serviceDescriptor..defaultNamespace::["operation"].length() == 0)
    {
        // All public methods of the given class will be marked as entry points
        var newAxisService = new Object();
        var methodName = "";

        var needToAddToArray = false;
        for each (var arrayElement in program.axisService) {
        if (arrayElement.namespaceName == thisAxisService.namespaceName && arrayElement.className == thisAxisService.className) {
            arrayElement.functionName = methodName;
            arrayElement.modifier = "public";
            needToAddToArray = false;
            break;
        }
        else {
            needToAddToArray = true;
        }
        }

        if (0 == program.axisService.length || needToAddToArray == true) {
        newAxisService.namespaceName = thisAxisService.namespaceName;
        newAxisService.className = thisAxisService.className;
        newAxisService.functionName = methodName;
        newAxisService.modifier = "public";

        program.axisService[program.axisService.length] = newAxisService;
        }

    }
    else {

        // User has specified individual methods to expose so let's model just those

        for each (var operation in serviceDescriptor..defaultNamespace::["operation"]) {
        var newAxisService = new Object();
        var methodName = "";

        // Extract each method's name
        methodName = String(operation["@name"]);

        // make sure we're dealing with valid Java method name
        if (methodName == null || false == isValidJavaIdentifier(methodName)) {
            continue;
        }

        // Determine if we need to add this new service to the existing array
        var needToAddToArray = false;
        for each (var arrayElement in program.axisService) {

            if (arrayElement.namespaceName == thisAxisService.namespaceName && arrayElement.className == thisAxisService.className) {
            arrayElement.functionName = arrayElement.functionName + "|" + methodName;
            needToAddToArray = false;
            break;
            }
            else {
            needToAddToArray = true;
            }
        }

        if (0 == program.axisService.length || needToAddToArray == true) {
            newAxisService.namespaceName = thisAxisService.namespaceName;
            newAxisService.className = thisAxisService.className;
            newAxisService.functionName = methodName;
            newAxisService.modifier = "";
            program.axisService[program.axisService.length] = newAxisService;
        }
        }
    }
    }
}

