        function init_struts2() {
          var ns = new Namespace("");
          var beanCount = 0;
          var actionCount = 0;
          program.struts_beans = new Array();
          program.struts_actions = new Array();
          for (var cfgName in program.xml) {
            var cfg = program.xml[cfgName];
            if (null != cfg) {
              if (cfg.name() != "struts") {
                continue;
              }
              for each (var j in cfg..ns::bean) {
                var thisBean = new Object();
                thisBean.name = String(j["@name"]);
                thisBean.clss =  String(j["@class"]);

                // make sure we're dealing with valid Java class
                if (false == isValidJavaPackageName(thisBean.clss)) {
                  continue;
                }

                var scope = String(j["@scope"]);
                var singleton_attr= String(j["@singleton"]);
                if (singleton_attr.toLowerCase() == "true" || (singleton_attr === null && (scope == "" || scope == null || scope == "singleton" || scope == "Singleton"))) {
                    thisBean.singleton = true;
                }

                program.struts_beans[beanCount++] = thisBean;
              }
              for each (var k in cfg..ns::action){
                var thisAction = new Object();
                thisAction.name = String(k["@name"]);
                thisAction.clss = String(k["@class"]);
                thisAction.fileName = cfgName;
                thisAction.lineNumber = 0;

                var dotIndex = thisAction.clss.lastIndexOf(".");
                thisAction.namespaceName = thisAction.clss.substring(0, dotIndex);
                thisAction.className = thisAction.clss.substr(dotIndex+1);

                // make sure we're dealing with valid Java class name
                if (null != thisAction.clss && 0 != thisAction.clss.length && isValidJavaPackageName(thisAction.clss)) {
                  program.struts_actions[actionCount++] = thisAction;
//alert("action namespace: " + thisAction.namespaceName);
//alert("action class: " + thisAction.className);
                }
              }
            }
          }
        }

        if (null == program.struts_beans || null == program.struts_actions) {
//alert("java: INITIALIZING STRUTS 2");
          init_struts2();
        }
        else {
//alert("java: STRUTS 2 HAS ALREADY BEEN INITIALIZED");
        }

