function addValidatedField(className, fieldName, fileName, lineNumber, actionFileName, actionLineNumber) {
  var thisResult = null;
  var resultArrayElement = new Object();
  resultArrayElement.fileNames = new Array();
  resultArrayElement.fileNames[0] = actionFileName;
  resultArrayElement.fileNames[1] = fileName;
  resultArrayElement.lineNumbers = new Array();
  resultArrayElement.lineNumbers[0] = actionLineNumber;
  resultArrayElement.lineNumbers[1] = lineNumber;
  resultArrayElement.source = "set" + fieldName.substr(0, 1).toUpperCase() + fieldName.substr(1);

  if (null == program.struts2_validated_fields[className]) {
    thisResult = new Array();
  }
  else {
    thisResult = program.struts2_validated_fields[className];
  }
  thisResult[thisResult.length] = resultArrayElement;
  program.struts2_validated_fields[className] = thisResult;
  dbg("validated field's setter: " + resultArrayElement.source);
}

function iterateOverNestedProperties(actionClass, inputValue, fileName, lineNumber, actionFileName, actionLineNumber) {
  var props = inputValue.split(".");

  var cName = actionClass;
  if (null != props) {
    for (var index = 0; index < props.length-1; index++) {
      if (isValidJavaIdentifier(props[index])) {
        var getter =  "get" + props[index].substr(0, 1).toUpperCase() + props[index].substr(1);
        cName = queryMetaTableForFunctionReturnType(cName, getter);
      }
    }
  }

  dbg("ADDING: cName: " + cName + ", fieldName: " + props[props.length-1]);
  addValidatedField(cName, props[props.length-1], fileName, lineNumber, actionFileName, actionLineNumber);
}

    //
    // Set up data structures for struts validators
    //
    function init_struts_validators() {
      var ns = new Namespace("");
      var valCount = 0;
      program.validators = new Array();
      for each (var cfg in program.xml) {
        if (null == cfg.name() || null == cfg.name().localName.match("validators")) {
          continue;
        }
        for each (var j in cfg..ns::validator) {
          var thisVal = new Object();
          thisVal.name = j["@name"];
          if (false == isDeclared(thisVal.name)) {
        program.validators[valCount++] = thisVal;
          }
        }
      }
      // add default validators that do not need to be declared
      var defaultVals = new Array("required", "requiredstring", "int", "long", "short", "double", "date", "expression", "fieldexpression", "email", "url", "visitor", "conversion", "stringlength", "regex", "conditionalvisitor");
      for each (var i in defaultVals) {
        var thisVal = new Object();
        thisVal.name = i;
        if (false == isDeclared(thisVal.name)) {
          program.validators[valCount++] = thisVal;
        }
      }
    }

    // check whether we already have that validator declared
    function isDeclared(vname) {
      if ("" == vname) {
        return true;
      }

      for each (var i in program.validators) {
        if (i.name == vname) {
          return true;
        }
      }
      return false;
    }

    if (null == program.validators) {
//alert("java: INITIALIZING STRUTS VALIDATORS");
      init_struts_validators();
    }
    else {
//alert("core_java: STRUTS VALIDATORS HAVE ALREADY BEEN INITIALIZED");
    }

function getAttribute(xmlElement, a) {
    var attributes = xmlElement.attributes();
    if (attributes != null) {
        for (var i = 0; i < attributes.length(); i++ ) {
            var attribute = attributes[ i ];
            if (attribute.name() == a) {
                if (attribute != null && String(attribute) != "")
                    return String(attribute);
            }
        }
    }
    return null;
}

function getPropAttributes (xmlElement, bean) {
    var pNs = new Namespace("http://www.springframework.org/schema/p");
    var ns = new Namespace("http://www.springframework.org/schema/beans");
    var propertyCounter = 0;

    // Collect all p:foo=bar pairs attribute automatically and store them in prop.name and prop.value
    for each(var nsprop in xmlElement.attributes()) {
        if (nsprop.namespace() == "http://www.springframework.org/schema/p") {
            var propHolder = new Object();
            propHolder.name = String(nsprop.localName()) ;
            propHolder.value = String(nsprop.toString()) ;
            bean.propertyElements[propertyCounter++] = propHolder;
        }
    }

    // Collect properties defined in property tags
    for each (var propElement in xmlElement.*) {
        if(propElement.name().localName == "property") {
            var propHolder = new Object();
            propHolder.element = propElement;
            var ens = new Namespace("");
            if (propElement["@name"] !== null && String(propElement["@name"]) != "") {
                propHolder.name = String (propElement["@name"]);
                if (propElement["@value"] != null && String(propElement["@value"]) != "") {
                    propHolder.value = String (propElement["@value"]);
                } else if (propElement.ns::value != null && String(propElement.ns::value) != "") {
                    propHolder.value = String (propElement.ns::value);
                }else if (propElement.ens::value != null && String(propElement.ens::value) != "") {
                    propHolder.value = String(propElement.ens::value);
                }  else if (propElement != null && String(propElement) != "") {
                    propHolder.value = String (propElement);
                } else {
                    propHolder.value = "";
                }
            }
            bean.propertyElements[propertyCounter++] = propHolder;
        }
    }

    // Now that we have collected all bean properties lets process them and add extra info
    for each(var prop in bean.propertyElements) {
        // If property was a reference, copy the ref to "ref" property
        if (prop.name.toLowerCase().indexOf("-ref") > 0) {
            prop.ref = prop.value;
        // If property was a MVC view,copy it to a specific property
        } else if (prop.name.toLowerCase() == "successview") {
            bean.successview = prop.value;
        } else if (prop.name.toLowerCase() == "formview") {
            bean.formview = prop.value;
        // Flag commandClass beans
        } else if (prop.name.toLowerCase() == "formobjectclass" || prop.name.toLowerCase() == "commandclass") {
            bean.isCommandClass = true;
        }

        // Process inner properties
        if (prop.element !== null && prop.element !== undefined) {
            // Process service beans
            if (prop.name.toLowerCase() == "service" || prop.name.toLowerCase() == "servicebean") {
                if (prop.element.ns::ref["@bean"] !== null && String(prop.element.ns::ref["@bean"]) != "") {
                    prop.ref = String(prop.element.ns::ref["@bean"]);
                } else if (prop.element["@ref"] !== null && String(prop.element["@ref"]) != "") {
                    prop.ref = String(prop.element["@ref"]);
                } else if (prop.element["@service-ref"] !== null && String(prop.element["@service-ref"]) != "") {
                    prop.ref = String(prop.element["@service-ref"]);
                } else {
                    prop.ref = String(prop.element);
                }
            }
            // Process validators
            else if (prop.name.toLowerCase() == "validator") {
                if (prop.element.ns::ref["@bean"] !== null && String(prop.element.ns::ref["@bean"]) != "") {
                    prop.ref = String(prop.element.ns::ref["@bean"]);
                } else if (prop.element["@ref"] !== null && String(prop.element["@ref"]) != "") {
                    prop.ref = String(prop.element["@ref"]);
                } else if (prop.element.ns::bean["@class"] !== null && String(prop.element.ns::bean["@class"]) != "") {
                    prop.value = String(prop.element.ns::bean["@class"]);
                }
            }
        }
    }
}

function isCommand(cls) {
    return endsWith(cls, "Controller") ||
            endsWith(cls, "Action") ||
            cls == "org.springframework.webflow.action.FormAction" ||
            isSubClass(cls, "org.springframework.web.servlet.mvc.BaseCommandController") ||
            isSubClass(cls, "org.springframework.webflow.action.FormAction");
}

function isRemoted(cls) {
    return cls == "org.springframework.remoting.caucho.HessianServiceExporter" ||
            cls == "org.springframework.remoting.caucho.BurlapServiceExporter" ||
            cls == "org.springframework.remoting.httpinvoker.HttpInvokerServiceExporter" ||
            cls == "org.springframework.remoting.httpinvoker.HttpInvokerProxyFactoryBean" ||
            isSubClass(cls, "org.springframework.remoting.support.RemoteAccessor") ||
            cls == "org.codehaus.xfire.spring.remoting.XFireExporter" ||
            isSubClass(cls, "org.codehaus.xfire.spring.remoting.XFireExporter") ||
            cls == "org.springframework.remoting.rmi.RmiServiceExporter" ||
            isSubClass(cls, "org.springframework.remoting.rmi.RmiServiceExporter") ||
            isSubClass(cls, "org.springframework.remoting.support.RemoteExporter");
}

function isJMSListenerAdapter(cls) {
    return cls == "org.springframework.jms.listener.adapter.MessageListenerAdapter";
}

// Set up data structures for spring beans
function init_spring() {
    var nsb4_2_0 = new Namespace("");//Before version 2.0, spring supports only DTD
    var ns = new Namespace("http://www.springframework.org/schema/beans");//From v2.0, spring supports XML Schema style
    var dwrns = new Namespace("http://www.directwebremoting.org/schema/spring-dwr");
    var flexNamespace = new Namespace("http://www.springframework.org/schema/flex");
    var pNs = new Namespace("http://www.springframework.org/schema/p");

    var springBeanCount = 0;
    program.spring_beans = new Array();
    program.spring_refs = new Object();
    program.spring_jms_listeners = new Object();
    for each (var cfg in program.xml) {
        if (null == cfg.name() || null == cfg.name().localName.match("beans")) {
            continue;
        }
        // consolidates beans in two different namespaces
        var beanElements = new Array();
        var springDTDbeans = 0;
        var springXSDbeans = 0;
        for each(var j in cfg..ns::bean){
            beanElements.push(j);
            springXSDbeans += 1;
        }
        for each(var j in cfg..nsb4_2_0::bean){
            beanElements.push(j);
            springDTDbeans += 1;
        }
        for each(var j in cfg..ns::bean){beanElements.push(j);}
        for each(var j in cfg..nsb4_2_0::bean){beanElements.push(j);}

        // Collect JMS listeners from jms namespace
        var jmsns = new Namespace("http://www.springframework.org/schema/jms");
        for each(var j in cfg..jmsns::listener) {
            if (j["@method"] === null || j["@method"] === undefined || String(j["@method"]) == "") continue;
            var ref = String(j["@ref"]);
            var method = String(j["@method"]);
            if (program.spring_jms_listeners[ref] === null || program.spring_jms_listeners[ref] === undefined) {
                program.spring_jms_listeners[ref] = [method];
            } else {
                var l = program.spring_jms_listeners[ref];
                l[l.length] = method;
                program.spring_jms_listeners[ref] = l;
            }
        }

        for each (var j in beanElements) {
            // Collect all bean names for future use in beans references
            var name = String(j["@id"]);
            var clss = String(j["@class"]);
            if (name.length == 0) name = String(j["@name"]);
            if (name.length > 0 && clss.length > 0) program.spring_refs[name] = clss;

            // Collect bean details
            var thisBean = new Object();
            thisBean.name = name;
            thisBean.clss = clss;

            var dotIndex = thisBean.clss.lastIndexOf(".");
            thisBean.namespaceName = thisBean.clss.substring(0, dotIndex);
            thisBean.className = thisBean.clss.substr(dotIndex+1);

            // make sure we're dealing with valid Java package and class names
            if (false == isValidJavaPackageName(thisBean.namespaceName) || false == isValidJavaIdentifier(thisBean.className)) {
                continue;
            }

            //Added the following block to access property elements
            thisBean.dwrRemote = false;
            thisBean.propertyElements = new Array();
            thisBean.isCommandClass = false;
            thisBean.isRemotedBean = false;
            thisBean.isSingleton = false;
            thisBean.isSessionScoped = false;
            thisBean.isApplicationScoped = false;
            thisBean.isJMSListenerAdapter = false;

            if (thisBean.clss) {
                var scope = String(j["@scope"]);
                var singleton_attr= String(j["@singleton"]);
                // Identify inner beans
                var innerbean = false;
                var parentnode = j.parent();
                while (parentnode !== null && parentnode !== undefined) {
                    var parentname = String(parentnode.localName());
                    if (parentname == "property" || parentname == "constructor-arg") {
                        innerbean = true;
                        break;
                    }
                    parentnode = parentnode.parent();
                }

                // Skip singleton analysis for inner beans
                if (!innerbean) {
                    // For Spring up to 2.0 using DTD
                    if (springDTDbeans > 0 && (singleton_attr.toLowerCase() == "true" || singleton_attr == null || singleton_attr == "")) {
                        thisBean.isSingleton = true;
                    }
                    // For Spring from 2.0 upwards
                    if (springXSDbeans > 0 && (scope == "" || scope == null || scope == "singleton" || scope == "Singleton")) {
                        thisBean.isSingleton = true;
                    }
                    if (springXSDbeans > 0 && (scope == "session" || scope == "globalSession")) {
                        thisBean.isSessionScoped = true;
                    }
                    if (springXSDbeans > 0 && scope == "application") {
                        thisBean.isApplicationScoped = true;
                    }
                }
                if (isCommand(thisBean.clss)) {
                    thisBean.isCommandClass = true;
                } else if (isRemoted(thisBean.clss)) {
                    thisBean.isRemotedBean = true;
                } else if (isJMSListenerAdapter(thisBean.clss)) {
                    thisBean.isJMSListenerAdapter = true;
                    for each (var l in j.ns::["constructor-arg"].ns::bean) {
                        if (String(l['@class']) != "") {
                            thisBean.listener = String(l['@class']);
                            break;
                        }
                    }
                    if (thisBean.listener === null || thisBean.listener === undefined || thisBean.listener == "") {
                        if (String(j.ns::["constructor-arg"]["@ref"]) != "") thisBean.listenerRef = String(j.ns::["constructor-arg"]["@ref"]);
                    }
                }
                getPropAttributes(j, thisBean);

                thisBean.jmxEntryElements = new Array();
                var entryCounter = 0;
                if ( thisBean.clss == "org.springframework.jmx.export.MBeanExporter") {
                    for each (var k in j.ns::property.ns::map.ns::entry) {
                        var entryHolder = new Object();
                        entryHolder.key = String(k["@key"]);
                        entryHolder.value_ref = String(k["@value-ref"]);
                        thisBean.jmxEntryElements[entryCounter++] = entryHolder;
                    }
                }
            }

            //End of new additions.
            thisBean.functionNamesInclude = new Array();
            var functionNamesIncludeCount = 0;
            var includeMethodName = "";
            for each (var k in j.dwrns::remote.dwrns::include) {
                thisBean.dwrRemote = true;
                includeMethodName = String(k["@method"]);

                // make sure we're dealing with valid Java identifier
                if (isValidJavaIdentifier(includeMethodName)) {
                    thisBean.functionNamesInclude[functionNamesIncludeCount++] = includeMethodName;
                }
            }

            thisBean.functionNamesExclude = new Array();
            var functionNamesExcludeCount = 0;
            var excludeMethodName = "";
            for each (var m in j.dwrns::remote.dwrns::exclude) {
                thisBean.dwrRemote = true;
                excludeMethodName = String(m["@method"]);

                // make sure we're dealing with valid Java identifier
                if (isValidJavaIdentifier(excludeMethodName)) {
                    thisBean.functionNamesExclude[functionNamesExcludeCount++] = excludeMethodName;
                }
            }

            if (thisBean.dwrRemote) {
                if ((0 < functionNamesExcludeCount) ||
                        ((0 == functionNamesIncludeCount) && (0 == functionNamesExcludeCount))) {
                    thisBean.functionNamesInclude[functionNamesIncludeCount++] = ".*";
                }
            }

            var flexRemotingDescriptionTag = j..flexNamespace::["remoting-destination"];

            if (flexRemotingDescriptionTag != null && flexRemotingDescriptionTag.length() > 0) {
                functionNamesIncludeCount = 0;
                functionNamesExcludeCount = 0;

                // Populate thisBean with relevant flex-remotable information
                var includedMethods = String(flexRemotingDescriptionTag["@include-methods"]);
                // alert("main processing route: targetBean = "+thisBean+"; remoting description tag (includedMethods: "+includedMethods+")");
                processBlazeSpringBean(thisBean, flexRemotingDescriptionTag);

            }

            program.spring_beans[springBeanCount++] = thisBean;
        }

        // Iterate through any high-level flex-remotable beans that are declared at the bean level
        var targetBean = null;
        for each (var flexRemotingDescriptionTag in cfg.flexNamespace::["remoting-destination"]) {
            var beanIdentifier = String(flexRemotingDescriptionTag["@ref"]);
            // alert("Bean identifier: " + beanIdentifier);
            for each (var proposedBean in program.spring_beans) {
                // alert("Iterated bean identifier: "+proposedBean.name);
                if (proposedBean.name == beanIdentifier) {
                    targetBean = proposedBean;
                    break;
                }
            }

            if (targetBean != null) {
                // alert("alternate processing route: targetBean = "+targetBean+"; remoting description tag = "+flexRemotingDescriptionTag);
                processBlazeSpringBean(targetBean, flexRemotingDescriptionTag);
            }
        }
    }
}

function processBlazeSpringBean(targetBean, flexRemotingDescriptionTag) {
    targetBean.flexRemote = true;

    var functionNamesIncludeCount = 0;
    var functionNamesExcludeCount = 0;

    // Process any explicitly declared "include methods"
    var includedMethods = String(flexRemotingDescriptionTag["@include-methods"]);
    if (includedMethods == null || includedMethods.length == 0) {
        // Include all public methods by default
        // alert("adding all methods of "+targetBean.className+" as flex exposed");
        targetBean.functionNamesInclude[functionNamesIncludeCount++] = "";
    }
    else {
        // Comma seperated list of methods to include
        var methodsArray = includedMethods.split(/[, \n]+/);
        for each (var method in methodsArray) {
            // make sure we're dealing with valid Java identifier
            if (isValidJavaIdentifier(method)) {
                targetBean.functionNamesInclude[functionNamesIncludeCount++] = method;
                // alert("adding method "+targetBean.className+"."+method+" as flex exposed");
            }
        }
    }

    // Process any explicitly declared "exclude methods"
    var excludedMethods = String(flexRemotingDescriptionTag["@exclude-methods"]);
    if (excludedMethods == null || excludedMethods.length == 0) {
        // Leave as blank
        targetBean.functionNamesExclude[functionNamesExcludeCount++] = "";
    }
    else {
        // Comma seperated list of methods to exclude
        var methodsArray = excludedMethods.split(/[, \n]+/);
        for each (var method in methodsArray) {
            // make sure we're dealing with valid Java identifier
            if (isValidJavaIdentifier(method)) {
                targetBean.functionNamesExclude[functionNamesExcludeCount++] = method;
                // alert("adding method "+targetBean.className+"."+method+" as flex excluded");
            }
        }
    }
}

