// NOTE: Integrate this
var defaultNamespace = new Namespace("");
var axisServiceCount = 0;
if (program.blazeService == null)
    program.blazeService = new Array();

for each (var servicesXMLFile in program.xml) {
    if (null == servicesXMLFile.name() || (servicesXMLFile.name().length == 0) || (null == servicesXMLFile.name().localName.match("service") && null == servicesXMLFile.name().localName.match("services-config"))) {
    continue;
    }

    var currentServiceElement = 0;
    var targetNode = null;

    if (servicesXMLFile.name().localName.match("services-config")) {
    // Multiple services being described
    targetNode = servicesXMLFile..defaultNamespace::["services"]..defaultNamespace::["service"];

    }
    else if (servicesXMLFile.name().localName.match("service")) {
    // Only one service being described
    targetNode = servicesXMLFile;
    }

    for each (var serviceDescriptor in targetNode) {

    var thisBlazeService = new Object();
    thisBlazeService.className = "";
    thisBlazeService.namespaceName = "";
    thisBlazeService.functionName = "";
    thisBlazeService.modifier = "";

    // Verify that this is the right service object we are looking for
    if (!serviceDescriptor.hasOwnProperty("@class"))
        continue;

    var serviceName = String(serviceDescriptor.attribute("class"));

    if (!serviceName || (serviceName.toLowerCase() != "flex.messaging.services.remotingservice"))
        continue;

    // Iterate through each destination

    var destinationClassCount = serviceDescriptor..defaultNamespace::["destination"].length();
    if (destinationClassCount == 0) {
        continue;
    }

    var destinationNodes = targetNode..defaultNamespace::["destination"];
    for each (var destinationNode in destinationNodes) {
        // Discover each destination class
        var classFactory = String(destinationNode..defaultNamespace::["properties"]..defaultNamespace::["factory"]);
        if (classFactory != null && classFactory.length > 0) {
        // We currenty do not cover custom factory-classes; this is too difficult to model
        continue;
        }

        thisBlazeService.className = String(destinationNode..defaultNamespace::["properties"]..defaultNamespace::["source"]);

        if (thisBlazeService.className == null || thisBlazeService.className.length == 0) {
        continue;
        }

        var dotIndex = thisBlazeService.className.lastIndexOf(".");

        if (dotIndex == -1) {
        thisBlazeService.namespaceName = "";
        }
        else {
        thisBlazeService.namespaceName = thisBlazeService.className.substring(0, dotIndex);
        thisBlazeService.className = thisBlazeService.className.substr(dotIndex + 1);
        }

        // make sure we're dealing with valid Java package and class names
        if (false == isValidJavaPackageName(thisBlazeService.namespaceName) || false == isValidJavaIdentifier(thisBlazeService.className)) {
          continue;
        }

        // All public methods of the given class will be marked as entry points
        var newBlazeService = new Object();
        var methodName = "";

        var needToAddToArray = false;
        for each (var arrayElement in program.blazeService) {
        if (arrayElement.namespaceName == thisBlazeService.namespaceName && arrayElement.className == thisBlazeService.className) {
            arrayElement.functionName = methodName;
            arrayElement.modifier = "public";
            needToAddToArray = false;
            break;
        }
        else {
            needToAddToArray = true;
        }
        }

        if (0 == program.blazeService.length || needToAddToArray == true) {
        newBlazeService.namespaceName = thisBlazeService.namespaceName;
        newBlazeService.className = thisBlazeService.className;
        newBlazeService.functionName = methodName;
        newBlazeService.modifier = "public";
        program.blazeService[program.blazeService.length] = newBlazeService;
        }
    }
    }
}

