// Iterate through each known spring bean and add the flex-remoting-enabled ones to the program.blazeService array
for each (var springBean in program.spring_beans) {
   if (springBean.flexRemote == true) {
       // alert("adding known spring bean "+springBean.className+" to blazeService array");
       // Add this bean to the program.blazeService array
       var thisBlazeService = new Object();
       thisBlazeService.className = springBean.className;
       thisBlazeService.namespaceName = springBean.namespaceName;
       thisBlazeService.modifier = "public";

       if (springBean.functionNamesInclude == null)
      thisBlazeService.functionName = "";
       else {
       // We have a string of include methods in an array
       var includeMethods = "";
       for each (var methodName in springBean.functionNamesInclude) {
           if (includeMethods.length == 0)
           includeMethods = methodName;
           else {
           includeMethods += "|";
           includeMethods += methodName;
           }
       }
       thisBlazeService.functionName = includeMethods;
       }

       // Consider Exclusions

       if (springBean.functionNamesExclude != null) {
      var excludedMethods = "";
      for each (var methodName in springBean.functionNamesExclude) {
          if (excludedMethods.length == 0)
          excludedMethods = methodName;
          else {
          excludedMethods += "|";
          excludedMethods += methodName;
          }
      }

      if (excludedMethods.length > 0) {
          if (thisBlazeService.functionName.length > 0)
         thisBlazeService.functionName += "|";

          thisBlazeService.functionName += "[^(" + excludedMethods + ")]";
      }
       }


       if (program.blazeService == null)
       program.blazeService = new Array();

       // alert("thisBlazeService (className: "+thisBlazeService.className+"; "+"namespace: "+thisBlazeService.namespaceName+"; "+"modifier: "+thisBlazeService.modifier+"; "+"methods: "+thisBlazeService.functionName+" )");
       program.blazeService[program.blazeService.length] = thisBlazeService;
   }
}

