function expandStructuralMatch(template, rule) {
  if (null == String(rule.StructuralMatch).match("FORTIFYCLASSSUBSTITUTION") &&
      null == String(rule.StructuralMatch).match("FORTIFYCLASSMEMBERSUBSTITUTION")) {
    rule.StructuralMatch = String(rule.StructuralMatch).replace("))", template);
  }
  return rule;
}

function modifyStructuralMatch(classToUse, classMemberToUse, rule) {
  rule.StructuralMatch = String(rule.StructuralMatch).replace(/FORTIFYCLASSSUBSTITUTION/, classToUse);
  rule.StructuralMatch = String(rule.StructuralMatch).replace(/FORTIFYCLASSMEMBERSUBSTITUTION/, classMemberToUse);
  return rule;
}

function arrayContains(arr, ele) {
  for each (var i in arr) {
    if (i == ele) {
      return true;
    }
    else {
      return false;
    }
  }
}

function addToArray(arr, ele) {
  if (null == arr || null == ele || true == arrayContains(arr, ele)) {
    return false;
  }
  arr[arr.length] = ele;
  return true;
}

