    function getInfoAboutVOsAndEOs(pageFile, AM) {
      for (var xmlFile in program.xml) {
        if (null != xmlFile.match(AM)) {
          //alert("matched: " + xmlFile);
          //var AMXML = getXMLForFilename(xmlFile);
          var AMXML = new XML(program.xml[xmlFile]);
          if (null != AMXML) {
        var thisAM = new Object();
        thisAM.xmlfilename = xmlFile;
        thisAM.fullclss = String(AMXML["@ComponentClass"]);

        // make sure we're dealing with valid Java class name
        if (false == isValidJavaPackageName(thisAM.fullclss)) {
          continue;
        }

        getInfoAboutCOs(pageFile, thisAM.fullclss);

        thisAM.namespace = thisAM.fullclss.substr(0, thisAM.fullclss.lastIndexOf("."));
        thisAM.clss = thisAM.fullclss.substr(thisAM.fullclss.lastIndexOf(".") + 1);
        //alert("thisAM.namespace: " + thisAM.namespace);
        //alert("thisAM.clss: " + thisAM.clss);
        thisAM.VOs = new Array();
        for each (var viewUsage in AMXML..ViewUsage) {
          var thisVO = new Object();
          thisVO.Name = String(viewUsage["@Name"]);
          //alert("thisVO.Name: " + thisVO.Name);
          thisVO.ViewObjectName = String(viewUsage["@ViewObjectName"]);
          //alert("thisVO.ViewObjectName: " + thisVO.ViewObjectName);
          for (var anotherXMLFile in program.xml) {
            if (null != anotherXMLFile.match(thisVO.ViewObjectName)) {
              //alert("another matched: " + anotherXMLFile);
              //var VOXML = getXMLForFilename(anotherXMLFile);
              var VOXML = new XML(program.xml[anotherXMLFile]);
              if (null != VOXML) {
            thisVO.xmlfilename = anotherXMLFile;
            thisVO.componentfullclss = String(VOXML["@ComponentClass"]);
            thisVO.componentnamespace = thisVO.componentfullclss.substr(0, thisVO.componentfullclss.lastIndexOf("."));
            thisVO.componentclss = thisVO.componentfullclss.substr(thisVO.componentfullclss.lastIndexOf(".") + 1);
            thisVO.rowfullclss = String(VOXML["@RowClass"]);
            thisVO.rownamespace = thisVO.rowfullclss.substr(0, thisVO.rowfullclss.lastIndexOf("."));
            thisVO.rowclss = thisVO.rowfullclss.substr(thisVO.rowfullclss.lastIndexOf(".") + 1);
            //alert("thisVO.componentnamespace: " + thisVO.componentnamespace);
            //alert("thisVO.componentclss: " + thisVO.componentclss);
            //alert("thisVO.rownamespace: " + thisVO.rownamespace);
            //alert("thisVO.rowclss: " + thisVO.rowclss);

            // make sure we're dealing with valid Java package and class names
            if (false == isValidJavaPackageName(thisVO.rownamespace) || false == isValidJavaIdentifier(thisVO.rowclss)) {
              continue;
            }

            thisVO.EOs = new Array();
            for each (var entityUsage in VOXML..EntityUsage) {
              var thisEO = new Object();
              thisEO.Name = String(entityUsage["@Name"]);
              thisEO.Entity = String(entityUsage["@Entity"]);
              //alert("thisEO.Name: " + thisEO.Name);
              //alert("thisEO.Entity: " + thisEO.Entity);
              for (var yetAnotherXMLFile in program.xml) {
                if (null != yetAnotherXMLFile.match(thisEO.Entity)) {
                  //alert("yet another matched: " + yetAnotherXMLFile);
                  //var EOXML = getXMLForFilename(yetAnotherXMLFile);
                  var EOXML = new XML(program.xml[yetAnotherXMLFile]);
                  if (null != EOXML) {
                thisEO.xmlfilename = yetAnotherXMLFile;
                thisEO.rowfullclss = String(EOXML["@RowClass"]);
                thisEO.rownamespace = thisEO.rowfullclss.substr(0, thisEO.rowfullclss.lastIndexOf("."));
                thisEO.rowclss = thisEO.rowfullclss.substr(thisEO.rowfullclss.lastIndexOf(".") + 1);
                //alert("thisEO.rownamespace: " + thisEO.rownamespace);
                //alert("thisEO.rowclss: " + thisEO.rowclss);

                // make sure we're dealing with valid Java package and class names
                if (false == isValidJavaPackageName(thisEO.rownamespace) || false == isValidJavaIdentifier(thisEO.rowclss)) {
                  continue;
                }

                thisEO.Attributes = new Array();
                for each (var attribute in EOXML..Attribute) {
                  var thisAttribute = new Object();
                  thisAttribute.Name = String(attribute["@Name"]);
                  thisAttribute.ColumnName = String(attribute["@ColumnName"]).replace(/_/g, "");
                  //alert("thisAttribute.Name: " + thisAttribute.Name);
                  //alert("thisAttribute.ColumnName: " + thisAttribute.ColumnName);

                  // make sure we're dealing with valid Java identifier
                  if (isValidJavaIdentifier(thisAttribute.ColumnName)) {
                    thisEO.Attributes[thisAttribute.Name] = thisAttribute;
                  }
                }
                  }
                }
              }
              thisVO.EOs[thisEO.Name] = thisEO;
            }

            thisVO.ViewAttributes = new Array();
            for each (var viewAttribute in VOXML..ViewAttribute) {
              var thisAttribute = new Object();
              thisAttribute.Name = String(viewAttribute["@Name"]);
              thisAttribute.AliasName = String(viewAttribute["@AliasName"]).replace(/_/g, "");
              thisAttribute.EntityUsage = String(viewAttribute["@EntityUsage"]);
              thisAttribute.EntityAttrName = String(viewAttribute["@EntityAttrName"]);

              // make sure we're dealing with valid Java identifier
              if (isValidJavaIdentifier(thisAttribute.AliasName)) {
                thisVO.ViewAttributes[thisAttribute.Name] = thisAttribute;
              }
              //alert("thisAttribute.Name: " + thisAttribute.Name);
              //alert("thisAttribute.AliasName: " + thisAttribute.AliasName);
              //alert("thisAttribute.EntityUsage: " + thisAttribute.EntityUsage);
              //alert("thisAttribute.EntityAttrName: " + thisAttribute.EntityAttrName);
            }
              }
            }
          }
          thisAM.VOs[thisVO.Name] = thisVO;
        }
        program.OA_AMs[AM] = thisAM;
        program.OA_Pages[pageFile] = thisAM;
          }
        }
      }
    }

    function getInfoAboutCOs(pageFile, AMFullClss) {
      var xmlPage = new XML(program.xml[pageFile]);

      // check root element first
      var controllerClss = String(xmlPage["@controllerClass"]);

      // make sure we're dealing with valid Java package name
      if (isValidJavaPackageName(controllerClss)) {
        handleControllerClassInfo(AMFullClss, controllerClss);
        var extendsTag = String(xmlPage["@extends"]);
        handleExtends(extendsTag, AMFullClss);
      }

      // now check the children
      for each (var tag in xmlPage..oans::*) {
        var controllerClss = String(tag["@controllerClass"]);

        // make sure we're dealing with valid Java package name
        if (isValidJavaPackageName(controllerClss)) {
          handleControllerClassInfo(AMFullClss, controllerClss);
          var extendsTag = String(tag["@extends"]);
          handleExtends(extendsTag, AMFullClss);
        }
      }
    }

    function handleControllerClassInfo(AMFullClss, controllerClss) {
      if (null != controllerClss && 0 != controllerClss.length) {
        if (null == program.OA_COsToAMs[controllerClss]) {
          var AMs = new Array();
          AMs[AMs.length] = AMFullClss;
          program.OA_COsToAMs[controllerClss] = AMs;
          //alert("adding mapping between " + controllerClss + " and " + AMFullClss);
          //alert("MAP: " + program.OA_COsToAMs[controllerClss][0]);
        }
        else {
          var AMs = program.OA_COsToAMs[controllerClss];
          addToArray(AMs, AMFullClss);
          //alert("adding to mapping between " + controllerClss + " and " + AMFullClss);
        }
      }
    }

    function handleExtends(extendsTag, AMFullClss) {
      if (null != extendsTag && 0 != extendsTag.length) {
        for (var xmlFile in program.xml) {
          if (null != xmlFile.match(extendsTag)) {
        //alert("matched extends: " + xmlFile);
        getInfoAboutCOs(xmlFile, AMFullClss);
          }
        }
      }
    }

    function getInfoAboutInputsAndOutputs(pageFile) {
      var xmlPage = new XML(program.xml[pageFile]);
      // check root node
      handleInputOutputTag(xmlPage);
      //for each (var tag in xmlPage..oans::messageTextInput) {
      // check children
      for each (var tag in xmlPage..oans::*) {
        handleInputOutputTag(tag);
      }
    }

    function handleInputOutputTag(tag) {
      var tagName = tag.localName();
      //alert("LOCAL: " + tagName);
      //if (null == isInputTag[tagName]) {
      //  return;
      //}

      var thisTag = new Object();
      thisTag.xmlfilename = pageFile;
      thisTag.viewName = String(tag["@viewName"]);
      thisTag.viewAttr = String(tag["@viewAttr"]);
      if (null != thisTag.viewName && null != thisTag.viewAttr &&
          0 != thisTag.viewName.length && 0 != thisTag.viewAttr.length) {
        //alert("thisTag.viewName: " + thisTag.viewName);
        //alert("thisTag.viewAttr: " + thisTag.viewAttr);
        if (true == isInputTag[tagName]) {
          program.OA_Inputs[program.OA_Inputs.length] = thisTag;
        }
        if (true == isOutputTag[tagName]) {
          program.OA_Outputs[program.OA_Outputs.length] = thisTag;
        }
      }
    }

