    // is the application loading dynamic libraries at runtime
    function processControlVuln()
    {
    var vulns = getVulnerabilities();
    for each (var vuln in vulns)
{
   var rule = vuln.getRule();
   var ruleID = String(rule.getIdentifier());

   for each ( var id in process_control_ruleIDs )
   {
 if(ruleID.indexOf(id) == 0)
 {
     return true;
 }
   }
}
        return false;
    }

    function remove_securitymanager_bypass_vuln( IDs )
    {

    var vulns = getVulnerabilities();
    for each (var vuln in vulns)
{
    var rule = vuln.getRule();
    var ruleID = String(rule.getIdentifier());

    for each (var id in IDs)
    {
       if(ruleID.equals(id))
   {
                   //alert("removing: " + id );
       vuln.remove();
       continue;
   }
    }
 }
    }

    // If no JNI or Process Control findings are present then remove Access Control SecurityManager Bypass vulns.
    if ( !processControlVuln() ) {
         remove_securitymanager_bypass_vuln( securitymanager_bypass_ruleIDs );
    }

