//
// This function queries MetaTable for a return type of a function fName defined in class cName or its superclasses.
//
function queryMetaTableForFunctionReturnType(cName, fName) {
  if (null != cName && null != fName && (typeof nameTable.getClassByName != 'undefined')) {
    var dotIndex = cName.lastIndexOf(".");
    if (-1 != dotIndex) {
      var actualClass = nameTable.getClassByName(cName.substring(0, dotIndex), cName.substr(dotIndex+1), "java");
      var result =  queryMetaTableForFunctionReturnTypeHelper(actualClass, fName);
      if ("" == result) {
        if (null != actualClass && actualClass.getName() != "[UnknownType]") {
          var superClasses = actualClass.getSuperClasses();
          if (null != superClasses) {
            for (var i = 0; i < superClasses.length; i++) {
              result = queryMetaTableForFunctionReturnTypeHelper(superClasses[i], fName);
              if ("" != result) {
                return result;
              }
            }
          }
        }
      }
      else {
        return result;
      }
    }
  }
  return "";
}

function queryMetaTableForFunctionReturnTypeHelper(actualClass, fName) {
  if (null != actualClass && actualClass.getName() != "[UnknownType]") {
    var methods = actualClass.getMethods();
    if (null != methods) {
      for (var i = 0; i < methods.length; i++) {
        if (methods[i].getName() == fName) {
          return methods[i].getReturnType().getPackageName() + "." + methods[i].getReturnType().getName();
        }
      }
    }
  }
  return "";
}

// NOTE: Integrate this
// Set up data structures for hibernate entities
//

function init_hibernate_config() {
  var ns = new Namespace("");
  var hibernateEntityCounter = 0;

  program.hibernate_config_entities = new Array();
  for each (var cfg in program.xml) {
    var hibernateEntity = new Object();
    if (null == cfg.name() || null == cfg.name().localName.match("hibernate-mapping")) {
      continue;
    }  else {
    //alert("######## Found Hibernate Config #########");
        if (null != cfg["@package"] && "" != String(cfg["@package"])) {
           hibernateEntity.pkg = String(cfg["@package"]);
           hibernateEntity.hasPackage = true;
        } else {
           hibernateEntity.hasPackage = false;
        }

        //alert("Does hibernateEntity have package: " + hibernateEntity.hasPackage);
    }

    cfg = new XML(cfg);
    //alert(cfg);
    for each (var j in cfg["class"]) {
      //alert("************** Looking at Hibernate entity " + j["@name"]);
      hibernateEntity.cls = String(j["@name"]);

      var pk = j["id"];
      //alert("The hibernate pk is:  " + pk);
      if (pk == null || String(pk) == "") {
        var compKeyId = j.ns::["composite-id"];
        if (compKeyId != null && String(compKeyId) != "") {
          var compKeyHolder = new Object();
          compKeyHolder.cls = String(compKeyId["@class"]);
          compKeyHolder.compKeyFields = new Array();
          var compKeyCounter = 0;
          for each (var ckp in compKeyId.ns::["key-property"]) {
            compKeyHolder.compKeyFields[compKeyCounter++] = String(ckp["@name"]);
          }
          hibernateEntity.compKey = compKeyHolder;
        }
      } else {
        hibernateEntity.pkCol = String(pk["@name"]);
      }
      program.hibernate_config_entities[hibernateEntityCounter++] = hibernateEntity;
    }
  }
}

if (null == program.hibernate_config_entities) {
//alert("********* Calling init_hibernate_config() ********");
  init_hibernate_config();
}

var redirect_directives = new Array();
var open_redirects_issues = new Array();
var xss_issues = new Array();

var vulns = getVulnerabilities();
for (var i = 0; i < vulns.length; i++) {
    var vuln = vulns[i];
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
    var id = vuln.getRule().getIdentifier();
    if (String(id) == "210D0BA7-6898-474C-911F-FC3322B3B5DE0") {
        var redirect_directive = new Object();
        redirect_directive.primaryLine = vuln.getPrimaryLine();
        redirect_directive.primaryFile = vuln.getPrimaryFile();
        redirect_directives.push(redirect_directive);
        vuln.remove();
    }
    else if (String(id) == "44F68395-73CB-4912-942C-98DC34FA90D80") {
        xss_issues.push(i);
    }
    else if (String(id) == "3FEEB585-7B7D-4805-8D7B-084C8B999B0E0") {
        open_redirects_issues.push(i);
    }
}

// Remove Open Redirect issues if there are no evidences that "redirect:" directive is used
if (open_redirects_issues.length > 0) {
    if (redirect_directives.length == 0) {
        for each (var issue_idx in open_redirects_issues) {
            var issue = vulns[issue_idx];
            issue.remove();
        }
    } else {
        for each (var issue_idx in open_redirects_issues) {
            var issue = vulns[issue_idx];
            var remove_issue = true;
            for each (var directive in redirect_directives) {
                if (
                    issue.getPrimaryLine() == directive.primaryLine &&
                    issue.getPrimaryFile() == directive.primaryFile
                    ) {
                    remove_issue = false;
                }
            }
            if (remove_issue) issue.remove();
        }
    }
}
// Remove XSS issues if there are evidences that "redirect:" directives are used
if (xss_issues.length > 0 && redirect_directives.length > 0) {
    for each (var issue_idx in xss_issues) {
        var issue = vulns[issue_idx];
        var remove_issue = false;
        for each (var directive in redirect_directives) {
            if (
                issue.getPrimaryLine() == directive.primaryLine &&
                issue.getPrimaryFile() == directive.primaryFile
                ) {
                remove_issue = true;
            }
        }
        if (remove_issue) issue.remove();
    }
}

// Remove XStream injection issues originated in SpringMVC controllers when a catch all converter has been properly configured
var vulns=getVulnerabilities();
for each (var vuln in vulns) {
    var id = String(vuln.getRule().getIdentifier());
    if (id == "4FED0197-0D78-40A1-B6F9-E2B2C2DEB812") {
        var xmlFiles = getXMLConfigFileNames();
        var ns = new Namespace();
        var springns = new Namespace("http://www.springframework.org/schema/beans");
        var oxmns = new Namespace("http://www.springframework.org/schema/oxm");
        for each (var filename in xmlFiles) {
            try {
                var contents = readFile(filename);
                if (contents.charAt(0) != '<') {
                      contents = contents.substring(1);
                }
                var xml = new XML(contents);
                // XStream marshaller
                if (null !== xml && null !== xml.name() && null !== xml.name().localName && null !== xml.name().localName.match("beans")) {
                    for each (var bean in xml..springns::bean) {
                        if (String(bean["@class"]) == "org.springframework.oxm.xstream.XStreamMarshaller") {
                            for each (var prop in bean.springns::property) {
                                if (String(prop["@name"]) == "converters") {
                                    var index = 0;
                                    for each (var converter in prop..springns::bean) {
                                        if (index == 0 && converter["@class"] == "org.springframework.oxm.xstream.CatchAllConverter") {
                                            vuln.remove();
                                        }
                                        index++;
                                    }
                                }
                            }
                        }
                    }
                }
            } catch (err) {
               // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.
               // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
            }
        }
    }
}

if (isAndroidApp()) {
    // This script will remove SSRF issues from Android applications.
    var vulns=getVulnerabilities();
    for each (var vuln in vulns) {
        var cat = String(vuln.getRule().getCategory());
        if (cat == "Server-Side Request Forgery") {
            vuln.remove();
        }
    }
}

if (isAndroidApp()) {
    var vulns=getVulnerabilities();
    var candidates = new Array();
    var remove_candidates = false;
    for each (var vuln in vulns) {
        var id = String(vuln.getRule().getIdentifier());
        // Collect Missing Google Play Services Updated Security Provider
        if (id == "B9B07F1C-4E9E-46D5-A9BD-CC394F982CC0") {
            candidates.push(vuln);
        } else if (id == "B2E554FB-1F2F-4080-A0D5-B0070E964FD4") {
            remove_candidates = true;
        }
    }
    if (remove_candidates) {
        for each (var candidate in candidates) candidate.remove();
    }
}

ScriptDefinitions.ScriptDefinition:
function findAbsolutePaths(files, relative) {
    var results = [];
    for each (var file in files) {
        if (file.indexOf(relative, String(file).length - String(relative).length) !== -1) {
            results[results.length] = file;
        }
    }
    return results;
}

var strutsActions = loadPersistedObject("program.struts_actions2");
var files = getAllProgramFileNames();
if (strutsActions !== null) {
    openOGNLActionBeanMap();
    //alert("openOGNLActionBeanMap");
    for each (var action in strutsActions) {
        if (action !== null && action !== undefined && action.clss !== null && action.clss !== undefined && action.clss != "") {
            newOGNLActionBeanSubmap(action.clss);
            //alert("====================")
            //alert("newOGNLActionBeanSubmap: " + action.clss);
            for each (var view in action.views) {
                var paths = findAbsolutePaths(files, view);
                for each (var view in paths) {
                    addOGNLViewFile(view);
                    //alert("addOGNLViewFile: " + view);
                }
            }
        }
    }
    closeOGNLActionBeanMap();
    //alert("closeOGNLActionBeanMap");

}
//else {
//    alert("No actions");
//}

function processType(type, visited) {
    // Loop through nested fields in the given class if they are not primitive of java JDK classes
    if (type === null
        || type === undefined
        || type.getName() == "[UnknownType]"
        || type.isPrimitive()
        || type.getPackageName() === null
        || type.getPackageName().match(/^java/)
        || type.getPackageName().match(/^org\.springframework/)) {
        return;
    }
    var key = String(type.getPackageName() + "." + type.getName());
    //alert("CommandClass: " + key)
    if (visited[key] !== true) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields !== null && fields !== undefined) {
            // Loop through the command class fields and look for other non primitive
            // and non-JDK classes nested in the object
            for each (var new_field in fields) {
                processField(new_field, visited);
            }
        }
    }
}

function processField(field, visited) {
  if (field === null || field === undefined) {
      return;
  }
  field.setLabel("commandField");
  //alert("\tCommandField: " + field.getName())
  processType(field.getType(), visited);
}

// Collect all Spring command classes
var visited = {};
var sp2cc = nameTable.getClassesByLabel("spring2CommandObject", "java");
var sp3cc = nameTable.getClassesByLabel("spring3CommandObject", "java");
var cmclasses = null;
if (sp2cc === null && sp3cc !== null) cmclasses = sp3cc;
if (sp2cc !== null && sp3cc === null) cmclasses = sp2cc;
if (sp2cc !== null && sp3cc !== null) cmclasses = sp2cc.concat(sp3cc);
if (cmclasses != null) {
    for each (var cmclass in cmclasses) {
        processType(cmclass, visited);
    }
}

var vulns = getVulnerabilities();
if (isAndroidApp()) {
    var defaultFactoryRule = "58FB5A42-BA7F-460C-A60B-FF67B8CA0607";
    var removeCertPinningIssues = false;
    for each (var vuln in vulns) {
        var ruleID = String(vuln.getRule().getIdentifier());
        if (ruleID == defaultFactoryRule) {
            removeCertPinningIssues = true;
            vuln.remove();
        }
    }
    if (removeCertPinningIssues) {
        for each (var vuln in vulns) {
            var ruleID = String(vuln.getRule().getIdentifier());
            if (["DA6F3C64-0A25-40E5-AD59-85968AEC9EF0", // Java.Net DF 1
                    "B1F5D0B0-DE56-42DE-ACD2-B79107F3324D", // Java.Net DF 2
                    "09D93C59-75F1-448C-8B37-10D545E435E2", // Java.Net Semantic
                    "6F32FF87-B31E-4BC1-9CF1-8FB42AEA70B8", // Java.Net Semantic
                    "A7B775B3-B4D9-4827-A592-3067AA9D3BE5"  // Sink Source rule for SSL_URL
                ].indexOf(ruleID) > -1) {
                vuln.remove();
            }
        }
    }
} else {
    // Remove Java Certificate pinning issues from non-Android applications
    for each (var vuln in vulns) {
        var ruleID = String(vuln.getRule().getIdentifier());
        if (["DA6F3C64-0A25-40E5-AD59-85968AEC9EF0", // Java.Net DF 1
                "B1F5D0B0-DE56-42DE-ACD2-B79107F3324D", // Java.Net DF 2
                "09D93C59-75F1-448C-8B37-10D545E435E2", // Java.Net Semantic
                "6F32FF87-B31E-4BC1-9CF1-8FB42AEA70B8", // Java.Net Semantic
                "A7B775B3-B4D9-4827-A592-3067AA9D3BE5",  // Sink Source rule for SSL_URL
                "43B34F1C-DBE0-4B58-A5C7-96C91F69B26D0", // Apache HttpComponents DF 1 ('0' added due to characterization)
                "67F5CED0-A51C-42D7-A789-FFF952F58C49", // Apache HttpComponents DF 2
                "C1626FA5-5FBE-450E-9E65-BCF3B135F68D", // Inadequate Certificate Verification Semantic 1
                "3FF883E4-282F-4457-9D71-2B9D3B7E93C5", // Inadequate Certificate Verification Semantic 2
                "2D79EF35-2EBB-4733-90AA-283D4A140CB3"// Inadequate Certificate Verification Semantic 3
            ].indexOf(ruleID) > -1) {
            vuln.remove();
        }
    }
}

var classes = nameTable.getClassesByLabel("GWTServiceClass", "java");
if (classes != null) {
    for each (var c in classes) {
        var serviceClassName = nameTable.getLabelValue("GWTServiceClass", c);
        var serviceClass = nameTable.getClassByFullName(serviceClassName, "java");
        for each (var scmethod in serviceClass.getMethods()) {
            for each (var rcmethod in c.getMethods()) {
                if (rcmethod.getName() == scmethod.getName()) {
                    scmethod.setLabel("GWTEntryMethod");
                }
            }
        }
    }
}

var spring_beans = loadPersistedObject("program.spring_beans");
var spring2_validated_fields = new Array();
var spring3_validated_command_classes = new Array();
var spring2_command_class_Map = {};

// Fill Spring 2 CommandClass to callback map
var callbacks = nameTable.getMethodsByLabel("commandClass", "java");
if (callbacks != null) {
    for each (var cb in callbacks) {
        var element = new Object();
        element.callback = cb.getName();
        element.fileName = cb.getFileName();
        element.lineNumber = cb.getLineNumber();
        controllerClass = cb.getEnclosingClass().getPackageName() + "." + cb.getEnclosingClass().getName();
        element.commandClass = nameTable.getLabelValue("commandClass", cb);
        spring2_command_class_Map[controllerClass] = element;
        // alert("Controller " + controllerClass);
        // alert("CommandClass " + element.commandClass);
    }
}

// 1.1 Process Spring Command Classes annotated with JSR 303 validation annotations
var cmclasses = nameTable.getClassesByLabel("JSR303Validated", "java");
if (cmclasses != null) {
    for each (var cmclass in cmclasses) {
        if (cmclass != null) {
            var labels = cmclass.getLabels();
            if (labels != null) {
                for each (var label in labels) {
                    if (label == "spring3CommandObject") {
                        var cclassName = cmclass.getPackageName() + "." + cmclass.getName();
                        try {
                            //alert("Adding class " + cclassName + " as validated class in " + cmclass.getFileName());
                            addValidatedCommandClass(spring3_validated_command_classes, cclassName, cmclass.getFileName(), cmclass.getLineNumber());
                        } catch (err) {
                            log("Error getting filename and linenumber from class, maybe class is not user defined");
                        }
                    }
                }
            }
        }
    }
}

// 1.2, 1.3, 1.4 SpringValidatorFramework (SVF) set in the initBinder and run automatically with @Valid or run with validate
var cmclasses = nameTable.getClassesByLabel("spring3CommandObject", "java");
if (cmclasses != null) {
    for each (var cmclass in cmclasses) {
        if (cmclass != null) {
            var commandClass = cmclass.getPackageName() + "." + cmclass.getName();
            var labels = cmclass.getLabels();
            if (labels != null) {
                for each (var label in labels) {
                    if (label == "validatorClass") {
                        var validatorClass = nameTable.getLabelValue("validatorClass", cmclass);
                        if (validatorClass != null && validatorClass != "" && validatorClass != "undefined") {
                            if (validatorClass != "org.springframework.validation.Validator" && validatorClass != "org.springmodules.validation.bean.BeanValidator") {
                                var vclass = nameTable.getClassByFullName(validatorClass, "java");
                                if (vclass != null && vclass.getName() != "[UnknownType]") {
                                    // alert("We have a valid validator class: " + validatorClass);
                                    try {
                                        addValidatedCommandClass(spring3_validated_command_classes, commandClass, vclass.getFileName(), vclass.getLineNumber());
                                    } catch (err) {
                                        log("Error getting filename and linenumber from class, maybe class is not user defined");
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// 1.5 Spring 3 Global validators
var xmlFiles = getXMLConfigFileNames();
var visited = {};
var ns = new Namespace();
var springns = new Namespace("http://www.springframework.org/schema/beans");
var mvcns = new Namespace("http://www.springframework.org/schema/mvc");
for each (var filename in xmlFiles) {
    try {
        var contents = readFile(filename);
        if (contents.charAt(0) != '<') {
              contents = contents.substring(1);
        }
        var xml = new XML(contents);
        if (null != xml && null != xml.name() && null != xml.name().localName && null != xml.name().localName.match("beans")) {
            for each (var j in xml.children()) {
                if (null != j.name() && null != j.name().localName.match("annotation-driven")) {
                   if (String(j["@validator"]) != "") {
                       if (spring_beans != null) {
                            for each (var bean in spring_beans) {
                                if (bean.name == String(j["@validator"])) {
                                    className = bean.namespaceName + "." + bean.className;
                                    if (className != "org.springframework.validation.beanvalidation.LocalValidatorFactoryBean") {
                                        // Excluding LocalValidatorFactoryBean since they will be caught by the JSR303 labeling rules
                                        var vclass = nameTable.getClassByFullName(className, "java");
                                        if (vclass != null && vclass.getName() != "[UnknownType]") {
                                            var cmclasses = nameTable.getClassesByLabel("spring3CommandObject", "java");
                                            for each (var cmclass in cmclasses) {
                                                if (cmclass != null) {
                                                    var commandclass = cmclass.getPackageName() + "." + cmclass.getName();
                                                    if (!(commandclass in visited)) {
                                                        try {
                                                            addValidatedCommandClass(spring3_validated_command_classes, commandclass, vclass.getFileName(), vclass.getLineNumber());
                                                            visited[commandclass] = true;
                                                        } catch (err) {
                                                            log("Error getting filename and linenumber from class, maybe class is not user defined");
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                   }
                }
            }
        }
    } catch (err) {
        // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.
        // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
    }
}

if (spring_beans != null) {

    // 2.1. Find Command classes bound with controllers and validators in the Spring config file
    for each (var bean in spring_beans) {
        if (bean.isCommandClass) {
             var commandClass = "";
             var validatorClass = "";
             for each (var prop in bean.propertyElements) {
                 if (prop.name == "validator-ref" || prop.name == "validator") {
                     if (prop.ref != null && prop.ref != "") {
                         // alert("  Looking for ref: " + prop.ref);
                         for each (var bean2 in spring_beans) {
                             if (bean2.name == prop.ref) {
                                 // alert("  Validator class " + bean2.namespaceName + "." + bean2.className);
                                 validatorClass = bean2.namespaceName + "." + bean2.className;
                             }
                         }
                     } else if (prop.value != null && prop.value != "") {
                         // alert("  Validator class " + prop.value);
                         validatorClass = prop.value;
                     }
                 }
                 if (prop.name == "commandClass") {
                     // alert("  CommandClass " + prop.value)
                     commandClass = prop.value;
                 }

            }
             var vclass = nameTable.getClassByFullName(validatorClass, "java");
             var cmclass = nameTable.getClassByFullName(commandClass, "java");
             if (vclass != null && vclass.getName() != "[UnknownType]" && cmclass != null && cmclass.getName() != "[UnknownType]") {
                 var fields = cmclass.getFields();
                 if (fields != null) {
                     for each (var field in fields) {
                        // alert("  Adding " + commandClass + " field " + field.getName() + " to validated fields");
                        try {
                            addValidatedField(spring2_validated_fields, commandClass, field.getName(), vclass.getFileName(), vclass.getLineNumber());
                        } catch (err) {
                            log("Error getting filename and linenumber from class, maybe class is not user defined");
                        }
                     }
                 }
             }
             else if (vclass != null && vclass.getName() != "[UnknownType]" ) {
                 // 2.2 Where Command classes are not bound to the controoler in the XML file, get controller
                 controllerClass = bean.namespaceName + "." + bean.className;
                 // alert("We have a validator with no command class for cotroller "+ controllerClass);
                 var cclass = nameTable.getClassByFullName(controllerClass, "java");
                 if (cclass != null && cclass.getName() != "[UnknownType]") {
                    // alert("valid class");
                     var labels = cclass.getLabels();
                     if (labels != null) {
                        for each (var label in labels) {
                            // alert("label " + label);
                            if (label == "commandClass") {
                                // alert("controller is labeled with command class");
                                var commandClass = nameTable.getLabelValue("commandClass", cclass);
                                // alert("Find class " + commandClass);
                                commandClass = commandClass.substr(0,commandClass.indexOf("."));
                                // alert("Find class " + commandClass);
                                var allclasses = nameTable.getAllClasses("java");
                                var models = new Array();
                                for each (var clss in allclasses) {
                                    if (clss.getName() == commandClass) {
                                        models[models.length] = clss;
                                    }
                                }
                                if (models.length == 1) {
                                    cmclass = models[0];
                                    commandClass = cmclass.getPackageName() + "." + cmclass.getName();
                                    if (cmclass != null && cmclass.getName() != "[UnknownType]") {
                                        // alert("We have a valid command class: " + commandClass);
                                        var cmfields = cmclass.getFields();
                                        for each (var cmfield in cmfields) {
                                            // alert("  Adding " + commandClass + " field " + cmfield.getName() + " to validated fields");
                                            try {
                                                addValidatedField(spring2_validated_fields, commandClass, cmfield.getName(), vclass.getFileName(), vclass.getLineNumber());
                                            } catch (err) {
                                                log("Error getting filename and linenumber from class, maybe class is not user defined");
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                 }
            }
        }
    }

    if (null != spring2_validated_fields) {
        persistObject("program.spring2_validated_fields", spring2_validated_fields);
    }
    if (null != spring3_validated_command_classes) {
        persistObject("program.spring3_validated_command_classes", spring3_validated_command_classes);
    }
    if (null != spring2_command_class_Map) {
        persistObject("program.spring2_command_class_Map", spring2_command_class_Map);
    }

}

function addValidatedField(array, className, fieldName, fileName, lineNumber) {
     var thisResult = null;
     var resultArrayElement = new Object();
     resultArrayElement.fileNames = new Array();
     resultArrayElement.fileNames[0] = fileName;
     resultArrayElement.lineNumbers = new Array();
     resultArrayElement.lineNumbers[0] = lineNumber;
     resultArrayElement.source = "set" + fieldName.substr(0, 1).toUpperCase() + fieldName.substr(1);
     // alert("Adding setter " + resultArrayElement.source + " for index '" + className + "' with validator " + fileName + ":" + lineNumber );

     if (null == array[className]) {
         thisResult = new Array();
     } else {
         thisResult = array[className];
     }
     thisResult[thisResult.length] = resultArrayElement;
     array[className] = thisResult;
}

function addValidatedCommandClass(array, className, fileName, lineNumber) {
     var thisResult = null;
     var element = new Object();
     element.fileNames = new Array();
     element.fileNames[0] = fileName;
     element.lineNumbers = new Array();
     element.lineNumbers[0] = lineNumber;
     // alert("Adding command class " + className + " with validator " + fileName + ":" + lineNumber );

    if (array != null) {
        array[className] = element;
    }
}

//The remove function. Remove all the results that have an ID that matches one in the list that is passed through
function remove_rules(IDs)
{
    var vulns=getVulnerabilities();
    for each (var vuln in vulns)
    {
        var ruleRR=vuln.getRule();
        var ruleID=String(ruleRR.getIdentifier());

        for each (var id in IDs)
        {
            if(ruleID.equals(id))
            {
                //log("Remove XXESAPI rule:"+ruleID);
                vuln.remove();
                continue;
            }
        }
    }
}

