program.android_xml_callbacks = new Array();
program.android_masked_fields = new Array();
for (var filename in program.xml) {
    var cfg = program.xml[filename];
    if (null == cfg.name()) continue;

    // Check on Root element's attributes
    var id = null;
    var masked = false;
    for each (var attr in cfg.attributes()) {
        var name = attr.name();
        var value = attr;
        if (name == "http://schemas.android.com/apk/res/android::id")
            id = value;
        else if (name == "http://schemas.android.com/apk/res/android::inputType" && value == "textPassword")
            masked = true;
        else if (name == "http://schemas.android.com/apk/res/android::onClick" && program.android_xml_callbacks.indexOf(value) === -1)
            program.android_xml_callbacks.push(value);
    }
    if (masked && id != null && id.indexOf("/") > -1) {
        var field_name = id.split("/").slice(-1).pop();
        if (program.android_masked_fields.indexOf(field_name) === -1)
            program.android_masked_fields.push(field_name);
    }

    // Check on descendents' attributes
    for each (var j in cfg..*) {
        if ("textPassword" === String(j.@attributens::["inputType"])) {
            var id = String(j.@attributens::["id"]);
            var field_name = String(id.split("/").slice(-1).pop());
            if ("" != field_name && program.android_masked_fields.indexOf(field_name) === -1)
                program.android_masked_fields.push(field_name);
        }
        if ("" !== String(j.@attributens::["onClick"]) && undefined !== j.@attributens::["onClick"] && null !== j.@attributens::["onClick"]) {
            var callback = String(j.@attributens::["onClick"]);
            if (program.android_xml_callbacks.indexOf(callback) === -1)
                program.android_xml_callbacks.push(callback);
        }
    }
}

