     var exported = false
     var exported_flag = String(j.@attributens::exported)
     if (exported_flag !== "" && exported_flag !== undefined && exported_flag !== null) {
          if (exported_flag.toLowerCase() == "true") exported = true;
     }
     if (j.elementns::["intent-filter"] !== null && j.elementns::["intent-filter"] !== undefined) {
          if (j.elementns::["intent-filter"].children().length() > 0) exported = true;
     }
     if (exported) program.android_exported_activities[program.android_exported_activities.length++] = fullActivity;

