      // check whether we already know of this permission
      function isDeclared(pname) {
        if ("" == pname) {
          return true;
        }

        for each (var i in program.android_permissions) {
          if (i == pname) {
            return true;
          }
        }
        return false;
      }

      // figures out whether whether AndroidManifest.xml contains a permission
      // This method is uwed in scripted structural rules
      function doesManifestContain(name) {
