      function collect_metadata(component, element) {
          // Collect meta-data
          // application, x activity, provider, x receiver, x service, x activity-alias
          var elementns = new Namespace("");
          var attributens = new Namespace("http://schemas.android.com/apk/res/android");
          var mdata_vars = new Array();
          //alert("---> " + component);
          for each (var i in element.elementns::["meta-data"]) {
                  var mdata = new Object();
                  mdata['name'] = String(i.@attributens::name);
                  mdata['value'] = String(i.@attributens::value);
                  mdata['resource'] = String(i.@attributens::resource);
                  mdata_vars[mdata_vars.length] = mdata;
                  //alert('name: ' + mdata['name']);
                  //alert('value: ' + mdata['value']);
          }
          // Load component from nametable, if it fails put it in general bucket
          if (component !== "global") {
              var actualClass = null;
              var dotIndex = component.lastIndexOf(".");
              if (dotIndex > 0) {
                  actualClass = nameTable.getClassByName(component.substring(0, dotIndex), component.substr(dotIndex+1), "java");
              } else {
                  actualClass = nameTable.getClassByFullName(component, "java");
              }
              if (null === actualClass || actualClass.getName() == "[UnknownType]") component = "global";
          }
          if (mdata_vars.length > 0) {
              //alert(mdata_vars.length);
              program.android_metadata[component] = mdata_vars;
          }
      }

      // run the script only if it is an Android app
      if (null == program.android_permissions && true == isAndroidApp()) {
        dbg("java: INITIALIZING ANDROID PERMISSIONS");
        init_android_permissions();
      }
      else {
        dbg("core_android: ANDROID PERMISSIONs HAVE ALREADY BEEN INITIALIZED OR THIS IS NOT AN ANDROID APP");
      }

    var xmlFiles = getXMLConfigFileNames();
    var ns = new Namespace();
    var springns = new Namespace("http://www.springframework.org/schema/beans");
    var oxmns = new Namespace("http://www.springframework.org/schema/oxm");
    for each (var filename in xmlFiles) {
    try {
        var contents = readFile(filename);
        if (contents.charAt(0) != '<') {
              contents = contents.substring(1);
        }
        var xml = new XML(contents);
        // Castor Mapper
        if (null != xml && null != xml.name() && null != xml.name().localName && xml.name().localName == "mapping") {
            for each (var j in xml.children()) {
                if (null != j.name() && null != j.name().localName.match("class")) {
                    var cName = String(j["@name"]);
                    var dotIndex = cName.lastIndexOf(".");
                    if (-1 != dotIndex) {
                        var xmlClass = nameTable.getClassByName(cName.substring(0, dotIndex), cName.substr(dotIndex+1), "java");
                        //alert(xmlClass.getName());
                        if (xmlClass != null && xmlClass.getName() != "[UnknownType]"){
                            xmlClass.setLabel("XMLMapped");
                        }
                    }
                }
            }
        }
        // JAXB Mapper
        if (null != xml && null != xml.name() && null != xml.name().localName && xml.name().localName == "beans") {
            for each (var bean in xml..springns::bean) {
                if (String(bean["@class"]) == "org.springframework.oxm.jaxb.Jaxb2Marshaller") {
                    for each (var prop in bean.springns::property) {
                        if (String(prop["@name"]) == "classesToBeBound") {
                            for each (var cName in prop..springns::value) {
                                var dotIndex = cName.lastIndexOf(".");
                                if (-1 != dotIndex) {
                                    var xmlClass = nameTable.getClassByName(cName.substring(0, dotIndex), cName.substr(dotIndex+1), "java");
                                    //alert(xmlClass.getName());
                                    if (xmlClass != null && xmlClass.getName() != "[UnknownType]"){
                                        xmlClass.setLabel("XMLMapped");
                                    }
                                }
                            }
                        }
                    }
                }
            }
            for each (var j in xml.children()) {
                if (null != j.name() && j.name().localName == "jaxb2-marshaller") {
                    for each (var k in j.children()) {
                        if (null != k.name() && null != k.name().localName.match("class-to-be-bound")) {
                            var cName = String(k["@name"]);
                            var dotIndex = cName.lastIndexOf(".");
                            if (-1 != dotIndex) {
                                var xmlClass = nameTable.getClassByName(cName.substring(0, dotIndex), cName.substr(dotIndex+1), "java");
                                //alert(xmlClass.getName());
                                if (null != xmlClass && xmlClass.getName() != "[UnknownType]"){
                                    xmlClass.setLabel("XMLMapped");
                                }
                            }
                        }
                    }
                }
            }
        }
    } catch (err) {
        // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.
        // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
    }
}

// where all of the permission-protected methods will go
var results = new Array();

// checks whether the method is already in the list
function doResultsContain(name) {
  for each (var i in results) {
    if (i.key == name) {
      return true;
    }
  }
  return false;
}

function loadMap(android_map) {
    for (var key in android_map) {
      if (false == doResultsContain(key)) {
        var perms = android_map[key];
        if (null != perms) {
          var thisResult = new Object();
          var dotIndex = key.lastIndexOf(".");
          thisResult.key = key;
          thisResult.className = key.substring(0, dotIndex);
          thisResult.functionName = key.substr(dotIndex+1);
          dotIndex = thisResult.className.lastIndexOf(".");
      thisResult.namespaceName = thisResult.className.substring(0, dotIndex);
          thisResult.className = thisResult.className.substr(dotIndex+1);
      thisResult.permission = perms;
          if (false == doResultsContain(key)) {
            results[results.length] = thisResult;
          }
        }
      }
    }
}

function handleLabeling(namespaceName, className, functionName, label) {
  if (null != namespaceName && null != className && 0 != className.length) {
    var classType = nameTable.getClassByName(namespaceName, className, "java");
    if (null != classType && '[UnknownType]' != classType.getName()) {
      for each (var method in classType.getMethods()) {
        if (functionName == method.getName()) {
          //alert("put label '" + label + "' on method '" + method.getName() + "'");
          method.setLabel(label);
        }
      }
    }
  }
}

