var source_id_secondary="FF613576-989E-4ABD-B089-42BAD3DF7A7C";
var secondary_to_delete = {};

var vulns=getVulnerabilities();

for each (var vuln in vulns) {
          if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
          if (vuln !== null && (vuln.getRule() === null || vuln.getSourceRule() === null)) continue;

          var source_id = vuln.getSourceRule().getIdentifier();

          if (source_id.equals(source_id_preferred)) {
            var sink_id = vuln.getRule().getIdentifier() + vuln.getPrimaryFile() + vuln.getPrimaryLine();
            secondary_to_delete[sink_id] = true;
          }
    }

for each (var vuln in vulns) {
          if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
          if (vuln !== null && (vuln.getRule() === null || vuln.getSourceRule() === null)) continue;

          var source_id = vuln.getSourceRule().getIdentifier();

          if (source_id.equals(source_id_secondary)) {
            var sink_id = vuln.getRule().getIdentifier() + vuln.getPrimaryFile() + vuln.getPrimaryLine();
