}

// Find beans that are serialized with XStream
var xmlFiles = getXMLConfigFileNames();
var ns = new Namespace();
var springns = new Namespace("http://www.springframework.org/schema/beans");
var oxmns = new Namespace("http://www.springframework.org/schema/oxm");
for each (var filename in xmlFiles) {
    try {
        var contents = readFile(filename);
        if (contents.charAt(0) != '<') {
              contents = contents.substring(1);
        }
        var xml = new XML(contents);
        // XStream marshaller
        if (null !== xml && null !== xml.name() && null !== xml.name().localName && null !== xml.name().localName.match("beans")) {
            for each (var bean in xml..springns::bean) {
                if (String(bean["@class"]) == "org.springframework.oxm.xstream.XStreamMarshaller") {
                    for each (var prop in bean.springns::property) {
                        if (String(prop["@name"]) == "aliases") {
                            for each (var alias in prop..springns::prop) {
                                var xclass = nameTable.getClassByFullName(alias.text(), "java");
                                if (null !== xclass && xclass.getName() != "[UnknownType]") {
                                    xclass.setLabel("XStreamAlias");
                                    var superclasses = xclass.getSuperClasses();
                                    for each (var superclass in superclasses) {
                                        superclass.setLabel("XStreamAlias");
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    } catch (err) {
        // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.
        // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
    }
}

// remove the results that have source session.getId() (or Rule 959CBAC1-56B9-47CF-AEBF-766523F8582A )
// and sink some ResponseStream (or rule 28B6B5C0-D921-4EED-BA2B-F988C4936EF4 )
var source_id="959CBAC1-56B9-47CF-AEBF-766523F8582A";
var sink_id="28B6B5C0-D921-4EED-BA2B-F988C4936EF4";
var vulns=getVulnerabilities();
for each (var vuln in vulns)
{
    var ruleRR=vuln.getRule();
    var ruleID=String(ruleRR.getIdentifier());
    if(ruleID.equals(sink_id))
    {
        if(String(vuln.getSourceRule().getIdentifier()).equals(source_id))
        {
            //Check source ID
            vuln.remove();
        }
    }
}

     // Because of the bug in <= 3.7 scripting API, these two functions are put into a separate <Script/> element
     // The bug consisted in doing namespaceName + className (instead of namespaceName + "." + className) when actually looking up the types in the nameTable
