     // 3.7 version of this script does exactly this, while 3.9 version of the script assumes that the bug is fixed

    //
    // This funtion adds a label to a particular field of a class
    function addLabelToField(namespaceName, className, fieldName, labelToUse) {
//alert("i am in addLabelToField: " + namespaceName + " : " + className + " : " + fieldName + " : " + labelToUse);
      if(typeof nameTable.getClassByName != 'undefined') {
//alert("6666666666666666666666666666666");

        // see the comment at the top of this <Script/> why this line of code is necessary
        if (0 < namespaceName.length) {
          className = namespaceName + "." + className;
        }
        var beanClass = nameTable.getClassByName("", className, "java");

        if (null != beanClass && '[UnknownType]' != beanClass.getName()) {
//alert("class not null");
          var beanClassFields = beanClass.getFields();
          if (null != beanClassFields) {
//alert("fields not null");
        for (var i = 0; i < beanClassFields.length; i++) {
//alert("inside for loop");
          if (null != beanClassFields[i]) {
//alert("field not null: " + beanClassFields[i].getName());
            if (beanClassFields[i].getName() == String(fieldName)) {
//alert("in if after");
              beanClassFields[i].setLabel(labelToUse);
//alert("i set label " + labelToUse + " to field " + fieldName + " of class " + className);
              break;
            }
          }
        }
          }
        }
      }
    }

    //
    // This funtion adds a label to all fields of a class
    function addLabelToFields(namespaceName, className, labelToUse) {
      if(typeof nameTable.getClassByName != 'undefined') {
//alert("in first if");

        // see the comment at the top of this <Script/> why this line of code is necessary
        if (0 < namespaceName.length) {
          className = namespaceName + "." + className;
        }
//alert("className: " + className);
        var actionClass = nameTable.getClassByName("", className, "java");

        if (null != actionClass && '[UnknownType]' != actionClass.getName()) {
//alert("in second if: " + actionClass.getName());
          var actionClassFields = actionClass.getFields();
          if (null != actionClassFields) {
//alert("in third if: " + actionClassFields.length);
        for (var i = 0; i < actionClassFields.length; i++) {
//alert("here");
          if (null != actionClassFields[i]) {
//alert("adding label '" + labelToUse + "' to field '" + actionClassFields[i].getName() + "' in '" + namespaceName + "." + className + "'");
            actionClassFields[i].setLabel(labelToUse);
          }
        }
          }
        }
      }
    }

