                //
                // This function queries MetaTable for a return type of a function fName defined in class cName or its superclasses.
                //
                function queryMetaTableForFunctionReturnType(cName, fName) {
                  if (null != cName && null != fName && (typeof nameTable.getClassByName != 'undefined')) {
                    var dotIndex = cName.lastIndexOf(".");
                    if (-1 != dotIndex) {
                      var actualClass = nameTable.getClassByName(cName.substring(0, dotIndex), cName.substr(dotIndex+1), "java");
                      var result =  queryMetaTableForFunctionReturnTypeHelper(actualClass, fName);
                      if ("" == result) {
                        if (null != actualClass && actualClass.getName() != "[UnknownType]") {
                          var superClasses = actualClass.getSuperClasses();
                          if (null != superClasses) {
                            for (var i = 0; i < superClasses.length; i++) {
                              result = queryMetaTableForFunctionReturnTypeHelper(superClasses[i], fName);
                              if ("" != result) {
                                return result;
                              }
                            }
                          }
                        }
                      }
                      else {
                        return result;
                      }
                    }
                  }
                  return "";
                }

                function queryMetaTableForFunctionReturnTypeHelper(actualClass, fName) {
                  if (null != actualClass && actualClass.getName() != "[UnknownType]") {
                    var methods = actualClass.getMethods();
                    if (null != methods) {
                      for (var i = 0; i < methods.length; i++) {
                        if (methods[i].getName() == fName) {
                          return methods[i].getReturnType().getPackageName() + "." + methods[i].getReturnType().getName();
                        }
                      }
                    }
                  }
                  return "";
                }

            //
            // This function make sure that the string passed as an argument is a valid Java identifier
            //
            function isValidJavaIdentifier(inputString) {
              if (null != inputString.match(/[^A-Za-z0-9_]+/)) {
                return false;
              }
              else {
                return true;
              }
            }

            //
            // This function make sure that the string passed as an argument is a valid Java package name
            //
            function isValidJavaPackageName(inputString) {
              if (null != inputString.match(/[^A-Za-z0-9_\.]+/)) {
                return false;
              }
              else {
                return true;
              }
            }

            //
            // Parse web.xml for url extensions
            //
            function getURLExtensionFromFilterMapping(xmlnamespace, classname) {
              var sns = new Namespace(xmlnamespace);
              var actionExtensions = new Array();
              var actionExtensionsCount = 0;
              var urlPattern;

              // compute URL extensions
              for each (var configFile in program.xml) {
                if (null != configFile && null != configFile.name() && null != configFile.name().localName && null != configFile.name().localName.match("web-app")) {
                  for each (var def in configFile..sns::filter) {
                    if (def..sns::["filter-class"] == classname) {
                      for each (var mapping in configFile..sns::["filter-mapping"]) {
                        if (mapping..sns::["filter-name"] == def..sns::["filter-name"]) {
                          urlPattern = mapping..sns::["url-pattern"];
                          for each (var pattern in urlPattern) {
                            if (null != pattern.match(/\*\.+/)) {
                              actionExtensions[actionExtensionsCount++] = pattern.substring(1);
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
              return actionExtensions;
            }

            //
            // Parse web.xml for url extensions
            //
            function getURLExtensionFromServletMapping(xmlnamespace, classname) {
              var sns = new Namespace(xmlnamespace);
              var urlExtension = "";
              var urlRoot = "";
              var info = new Array();
              var counter = 0;

              // compute URL extensions
              for (var configFileName in program.xml) {
                dbg("configFileName: " + configFileName);
                dbg("other name: " + sns + "::web-app");
                if (null != program.xml[configFileName] && null != program.xml[configFileName].name() &&
                    null != program.xml[configFileName].name().localName && null != program.xml[configFileName].name().localName.match("web-app")) {
                  urlRoot = "";
                  var path = configFileName.replace(/\\/g, "/").split("/");
                  if (path[path.length-2] == "WEB-INF") {
                    var index = configFileName.lastIndexOf(path[path.length-2]);
                    urlRoot = configFileName.substring(0, index);
                    //dbg("urlRoot: " + urlRoot);
                  }
                  for each (var def in program.xml[configFileName]..sns::servlet) {
                    if (def..sns::["servlet-class"] == classname) {
                      for each (var mapping in program.xml[configFileName]..sns::["servlet-mapping"]) {
                        if (mapping..sns::["servlet-name"] == def..sns::["servlet-name"]) {
                          urlPattern = mapping..sns::["url-pattern"];
                          var roots = new Array();
                          for each (var pattern in urlPattern) {
                            if (null != pattern.match(/\*\.+/)) {
                              roots[roots.length] = pattern.substring(1);
                              counter++;
                            }
                          }
                          if (roots.length > 0){
                            info[urlRoot] = roots;
                          }
                        }
                      }
                    }
                  }
                }
              }
              if (0 == counter) {
                return null;
              }
              return info;
            }

            //
            // This function iterates over nested JSF properties with the help of the
            // getter function return type information retrieved from the MetaTable.
            //
            function iterateOverNestedProperties(beanClass, inputValue) {
              var props = getBeansAndProperty(inputValue);

              // getBeansAndProperty() makes sure that the contents of the returned array are valid Java identifiers, so we don't have to do more checks
              var cName = beanClass;
              for (var index = 1; index < props.length-1; index++) {
                var getter =  "get" + props[index].substr(0, 1).toUpperCase() + props[index].substr(1);
                cName = queryMetaTableForFunctionReturnType(cName, getter);
              }
              return cName;
            }

            function iterateOverFields(fieldsToUse, labelToUse, visited) {
                for(var i = 0; fieldsToUse != null && i < fieldsToUse.length; i++) {
                    propLabels(fieldsToUse[i], labelToUse, visited);
                }
            }

            function propLabels(fieldToUse, labelToUse, visited) {
                    visitField(fieldToUse, labelToUse, visited);
                    var fields = fieldToUse.getType().getFields();
                    for(var j = 0; fields != null && j < fields.length; j++) {
                            if (isVisited(fields[j], visited)) {
                                     continue;
                            }
                            else if(fields[j].getType().getFields() != null && fields[j].getType().getFields().length > 0) {
                                    propLabels(fields[j], labelToUse, visited);
                            }
                            else {
                                    visitField(fields[j], labelToUse, visited);
                            }
                    }
            }

            function getFieldID(field) {
                    return (field.getEnclosingClass().getPackageName() + "." + field.getEnclosingClass().getName() + "." + field.getName());
            }

            function visitField(field, labelToUse, visited) {
                    visited[getFieldID(field)] = true;
                    field.setLabel(labelToUse);
            }

            function isVisited(field, visited) {
                    return (getFieldID(field) in visited);
            }

            function dbg(msg) {
              //alert(msg);
            }

            // Function to split fully qualified classname into namespace (ns) and className (clsName).
            function splitFullyQualifiedClsName (fullyQualifiedClsName) {
              var dotIndex = String(fullyQualifiedClsName).lastIndexOf(".");
              var returnObj = new Object();
              returnObj.ns = String(fullyQualifiedClsName).substring(0, dotIndex);
              returnObj.clsName = String(fullyQualifiedClsName).substr(dotIndex+1);
              return returnObj;
            }

            // helper for isSubClass below
            function isSubClassHelper(subclass, targetName) {
                var directSupers = subclass.getSuperClasses();
                var found = false;

                if (directSupers == null || directSupers.length == 0)  {
                    return false;
                }

                for each (var sup in directSupers) {
                    var dsFullName = sup.getPackageName() ? sup.getPackageName() + "." + sup.getName()
                                                          : sup.getName();
                    if (targetName == dsFullName) {
                        return true;
                    }
                    found = found || isSubClassHelper(sup, targetName);
                }

                return found;
            }

            //
            // Returns a boolean based on whether subName is a descendent class of superName
            // subName and superName are both strings expressed as fully qualified class names, e.g., "java.util.List"
            //
            function isSubClass(subName, superName) {
                var clsIndex = subName.lastIndexOf(".");

                if (clsIndex == -1) {
                    return false;
                }

                var subPkgName = subName.substring(0, clsIndex);
                var subClsName = subName.substring(clsIndex+1);
                var subType = nameTable.getClassByName(subPkgName, subClsName, "java");

                if (!subType || subType.getName() == "[UnknownType]") {
                    return false;
                }

                return isSubClassHelper(subType, superName);
            }

        function addLabelToClass(namespaceName, className, labelToUse) {
            if(typeof nameTable.getClassByName != 'undefined') {
            var actionClass = nameTable.getClassByName(namespaceName, className, "java");
            if (null != actionClass && '[UnknownType]' != actionClass.getName()) {
            actionClass.setLabel(labelToUse);
            }
        }
}

ScriptDefinitions.ScriptDefinition:
function extractLabelValues(obj, prefix) {
    var values = [];
    if (obj !== null && prefix !== null && prefix !== "") {
        var labels = obj.getLabels();
        if (labels !== null) {
            for each (var l in labels) {
                if (l.indexOf(prefix) == 0) {
                        var value = String(l.substring(prefix.length));
                        if (value != null && value.length > 0) {
                                values[values.length++] = value;
                        }
                }
            }
        }
    }
    return values;
}

function extractAttributeName(str) {
    var prefix = "SpringELVisible";
    var first_delimiter = str.indexOf("::");
    var last_delimiter = str.lastIndexOf("::");
    if (str.indexOf(prefix) == 0 && first_delimiter > 0 && last_delimiter > 0 && last_delimiter !== first_delimiter) {
        return String(str.substring(prefix.length + 2, last_delimiter));
    }
    return null;
}

function extractAttributeType(str) {
    var prefix = "SpringELVisible";
    var first_delimiter = str.indexOf("::");
    var last_delimiter = str.lastIndexOf("::");
    if (str.indexOf(prefix) == 0 && first_delimiter > 0 && last_delimiter > 0 && last_delimiter !== first_delimiter) {
        return String(str.substring(last_delimiter + 2));
    }
    return null;
}

function generateFieldName(fieldType) {
    // ATTRIBUTE NAME AUTO GENERATION conventation:
    // Determine the conventional variable name for the supplied Object based on its concrete type. The convention used is to return the uncapitalized short name of the Class,
    // according to JavaBeans property naming rules: So, com.myapp.Product becomes product; com.myapp.MyProduct becomes myProduct; com.myapp.UKProduct becomes UKProduct.
    // For arrays, we use the pluralized version of the array component type. For Collections we attempt to 'peek ahead' in the Collection to determine the component
    // type and return the pluralized version of that component type.

    if (fieldType !== undefined && fieldType !== null) {
        var lastdot = fieldType.lastIndexOf(".");
        if (lastdot > 0) return fieldType.substring(lastdot + 1, lastdot + 2).toLowerCase() + fieldType.substring(lastdot + 2);
        else return null;
    } else return null;
}

var page_prefixes = ["/"];
var page_suffixes = [".jsp"];

// Retrieve view preffix and suffix from viewResolver calls
var classes = nameTable.getClassesByLabel("SpringMVCViewPrefix", "java");
if (classes !== null && classes !== undefined) {
for each (var c in classes) {
    var prefixes = extractLabelValues(c, "SpringMVCViewPrefix::");
        if (prefixes !== null && prefixes !== undefined) page_prefixes[page_prefixes.length] = prefixes[0];
    }
}
classes = nameTable.getClassesByLabel("SpringMVCViewSuffix", "java");
if (classes !== null && classes !== undefined) {
    for each (var c in classes) {
        var suffixes = extractLabelValues(c, "SpringMVCViewSuffix::");
        if (suffixes !== null && suffixes !== undefined) page_suffixes[page_suffixes.length] = suffixes[0];
    }
}


// Retrieve view preffix and suffix from viewResolver configuration.
// Possible ViewResolvers beans to extract the JSP (do we care for other types now?) prefix/suffix info from:
// - UrlBasedViewResolver
// - InternalResourceViewResolver
var spring_beans = loadPersistedObject("program.spring_beans");
for each (var bean in spring_beans) {
    if (bean.clss === "org.springframework.web.servlet.view.InternalResourceViewResolver" ||
        bean.clss === "org.springframework.web.servlet.view.UrlBasedViewResolver") {
        for each (var prop in bean.propertyElements) {
            if (prop.name === "prefix") page_prefixes[page_prefixes.length] = prop.value;
            if (prop.name === "suffix") page_suffixes[page_suffixes.length] = prop.value;
        }
    }
}

var map = {};                   // controller_method_name --> array of logic view names associated to the controller method
var methodname_method = {};     // controller_method_name --> jsMethod
var controller_methods = {};    // controller_method_name --> jsMethod

// Process view names collected from SimpleFormControllers.setSuccesssView (configuration)
var successMethods = ['onSubmit', 'processFormSubmission'];
for each (var bean in spring_beans) {
    if (bean !== null && bean !== undefined
        && bean.successview !== null && bean.successview !== undefined
        && bean.namespaceName !== null && bean.namespaceName !== undefined
        && bean.className !== null && bean.className !== undefined) {
        for each (var sm in successMethods) {
            var methodname = bean.namespaceName + "." + bean.className + "." + sm;
            var m = null;
            var cclass = nameTable.getClassByName(bean.namespaceName, bean.className, "java");
            if (null !== cclass && '[UnknownType]' !== cclass.getName()) {
                var methods = cclass.getMethods();
                for each (var method in methods) {
                    if (null !== method && '[UnknownType]' !== method.getName()) {
                        if (method.getName() == sm) {
                            m = method;
                            break;
                        }
                    }
                }
            }
            if (m !== null) {
                var views = map[methodname];
                if (views === null || views === undefined || views.length == 0) views = [];
                views[views.length] = bean.successview;
                map[methodname] = views;
                methodname_method[methodname] = m;
            }
            var cmethod = controller_methods[methodname];
            if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
        }
    }
}

// Process view names collected from SimpleFormControllers.setSuccesssView (programatically)
var classes = nameTable.getClassesByLabel("SpringMVCSimpleFormSuccessView", "java");
if (classes !== null && classes !== undefined) {
    for each (var c in classes) {
        for each (var sm in successMethods) {
            var methodname = String(c.getPackageName()) + "." + String(c.getName()) + "." + sm;
            var successview = extractLabelValues(c, "SpringMVCSimpleFormSuccessView::")[0];
            var m = null;
            var methods = c.getMethods();
            for each (var method in methods) {
                if (null !== method && '[UnknownType]' !== method.getName()) {
                    if (method.getName() == sm) {
                        m = method;
                        break;
                    }
                }
            }
            if (m !== null) {
                var views = map[methodname];
                if (views === null || views === undefined || views.length == 0) views = [];
                views[views.length] = successview;
                map[methodname] = views;
                methodname_method[methodname] = m;
            }
            var cmethod = controller_methods[methodname];
            if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
        }
    }
}

// Process view names collected from SimpleFormControllers.setFormView (configuration)
var formMethods = ['showForm', 'referenceData'];
for each (var bean in spring_beans) {
    if (bean !== null && bean !== undefined
        && bean.formview !== null && bean.formview !== undefined
        && bean.namespaceName !== null && bean.namespaceName !== undefined
        && bean.className !== null && bean.className !== undefined) {
        for each (var fm in formMethods) {
            var methodname = bean.namespaceName + "." + bean.className + "." + fm;
            var m = null;
            var cclass = nameTable.getClassByName(bean.namespaceName, bean.className, "java");
            if (null !== cclass && '[UnknownType]' !== cclass.getName()) {
                var methods = cclass.getMethods();
                for each (var method in methods) {
                    if (null !== method && '[UnknownType]' !== method.getName()) {
                        if (method.getName() == fm) {
                            m = method;
                            break;
                        }
                    }
                }
            }
            if (m !== null) {
                var views = map[methodname];
                if (views === null || views === undefined || views.length == 0) views = [];
                if (String(bean.formview) !== "") views.push(bean.formview);
                if (String(bean.successview) !== "") views.push(bean.successview);
                map[methodname] = views;
                methodname_method[methodname] = m;
            }
            var cmethod = controller_methods[methodname];
            if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
        }
    }
}

// Process view names collected from SimpleFormControllers.setFormView (programatically)
var classes = nameTable.getClassesByLabel("SpringMVCSimpleFormFormView", "java");
if (classes !== null && classes !== undefined) {
    for each (var c in classes) {
        for each (var fm in formMethods) {
            var methodname = String(c.getPackageName()) + "." + String(c.getName()) + "." + fm;
            var formview = extractLabelValues(c, "SpringMVCSimpleFormFormView::")[0];
            var m = null;
            var methods = c.getMethods();
            for each (var method in methods) {
                if (null !== method && '[UnknownType]' !== method.getName()) {
                    if (method.getName() == fm) {
                        m = method;
                        break;
                    }
                }
            }
            if (m !== null) {
                var views = map[methodname];
                if (views === null || views === undefined || views.length == 0) views = [];
                views[views.length] = formview;
                map[methodname] = views;
                methodname_method[methodname] = m;
            }
            var cmethod = controller_methods[methodname];
            if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
        }
    }
}

// Process view names collected from MultiActionController methods returning a Map
var methods = nameTable.getMethodsByLabel("SpringMVCMultiActionView", "java");
if (methods !== null && methods !== undefined) {
    for each (var m in methods) {
        var methodname = String(m.getEnclosingClass().getPackageName() + "." + m.getEnclosingClass().getName() + "." + m.getName());
        var controllername = m.getEnclosingClass().getName().toLowerCase().replace("controller", "");
        var viewname1 = controllername + "/" + m.getName().toLowerCase();
        var viewname2 = m.getName().toLowerCase();
        var views = map[methodname];
        if (views === null || views === undefined || views.length == 0) views = [];
        views[views.length] = viewname1;
        views[views.length] = viewname2;
        map[methodname] = views;
        methodname_method[methodname] = m;
        var cmethod = controller_methods[methodname];
        if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
    }
}

// Process absolute view names collected from ModelAndViews, Views and return strings
var methods = nameTable.getMethodsByLabel("SpringMVCAbsoluteView", "java");
if (methods !== null && methods !== undefined) {
    for each (var m in methods) {
        var viewnames = extractLabelValues(m, "SpringMVCAbsoluteView::");
        for each (var viewname in viewnames) {
            if (viewname.indexOf("redirect:") != 0 && viewname.indexOf("forward:") != 0) {
                var methodname = String(m.getEnclosingClass().getPackageName() + "." + m.getEnclosingClass().getName() + "." + m.getName());
                var views = map[methodname];
                if (views === null || views === undefined || views.length == 0) views = [];
                views[views.length] = viewname;
                map[methodname] = views;
                methodname_method[methodname] = m;
            }
            var cmethod = controller_methods[methodname];
            if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
        }
    }
}

// Collect Apache Tiles information
var templates = {};
for each (var cfg in program.xml) {
    if (null == cfg.name() || null == cfg.name().localName.match("tiles-definitions")) {
        continue;
    }
    for each (var j in cfg.*::['definition']) {
        var name = String(j["@name"]);
        var parent_template = String(j["@extends"]);
        var view_template = String(j["@template"]);
        var template = {};
        template.name = Math.random().toString(36).substring(7);
        template.parent_template = null;
        template.views = [];
        if (name != "") template.name = name
        if (parent_template != "") template.parent_template = parent_template;
        if (view_template != "") template.views.push(view_template);
        for each (var a in j..*::['put-attribute']) {
            var value = String(a["@value"]);
            if (value != "") template.views.push(value);
        }
        for each (var d in j..*::['definition']) {
            var nested_template = String(d["@template"]);
            if (nested_template!= "") template.views.push(nested_template);
        }
        templates[template.name] = template;
    }
}
var tilesviewmap = {};
for each (var t in templates) {
    //alert(t.name);
    var views = [];
    if (t.parent_template !== null && templates[t.parent_template] !== undefined) {
        for each (var v1 in templates[t.parent_template].views) {
            //alert("    " + v1)
            views.push(v1);
        }
    }
    for each (var v2 in t.views) {
        if (templates[v2] !== null && templates[v2] !== undefined) {
            for each (var v3 in templates[v2].views) {
                //alert("    " + v3)
                views.push(v3);
            }
        } else {
            //alert("    " + v2)
            views.push(v2);
        }
    }
    tilesviewmap[t.name] = views;
}
function getTilesViews(logicName, map) {
    logicName = logicName.replace(/^\//, '');
    var result = [];
    var logicNames = Object.keys(tilesviewmap);
    for each (var name in logicNames) {
        if (name == logicName) {
            for each(var v in tilesviewmap[name]) {
                //alert(v)
                result.push(v);
            }
        } else if (name.indexOf('*') > -1) {
            name_regexp = name.replace('*', '(.*)')
            res = logicName.match(name_regexp)
            if (res !== null && res.length > 0) {
                for each (var a in tilesviewmap[name]) {
                    final_name = a.replace('{1}', res[0])
                    //alert(final_name)
                    result.push(final_name);
                }
            }
        }
    }
    return result;
}
var isApacheTiles = Object.keys(tilesviewmap).length > 0;

// Process logic view names collected from ModelAndViews, Views and return strings
var methods = nameTable.getMethodsByLabel("SpringMVCView", "java");
if (methods !== null && methods !== undefined) {
    for each (var m in methods) {
        var viewnames = extractLabelValues(m, "SpringMVCView::");
        for each (var viewname in viewnames) {
            if (viewname.indexOf("redirect:") != 0 && viewname.indexOf("forward:") != 0) {
                var methodname = String(m.getEnclosingClass().getPackageName() + "." + m.getEnclosingClass().getName() + "." + m.getName());
                var views = map[methodname];
                if (views === null || views === undefined || views.length == 0) views = [];
                for each (var prefix in page_prefixes) {
                    for each (var suffix in page_suffixes) {
                        vn = prefix + viewname + suffix;
                        vn = String(vn).replace(/\/\//g,'/');
                        vn = String(vn).replace(/\\\\/g,'\\');
                        views[views.length] = vn;
                    }
                }
                if (isApacheTiles) {
                    for each(var atv in getTilesViews(viewname)) {
                        views[views.length] = atv;
                    }
                }
                map[methodname] = views;
                methodname_method[methodname] = m;
            }
            var cmethod = controller_methods[methodname];
            if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
        }
    }
}

// Process view names collected from RequestMapping annotations
var methods = nameTable.getMethodsByLabel("SpringMVCMapping", "java");
if (methods !== null && methods !== undefined) {
    for each (var m in methods) {
        var viewname = extractLabelValues(m, "SpringMVCMapping::")[0];
        var controller_prefix = extractLabelValues(m, "SpringMVCControllerMapping::")[0];
        if (controller_prefix !== undefined && controller_prefix !== null && controller_prefix !== "") {
                viewname = controller_prefix + viewname;
        }
        var pathindex = viewname.indexOf('{');
        if (pathindex > 0) {
            viewname = viewname.substr(0,pathindex-1);
        }
        if (!String(viewname).match(/\*|{.*}/)) {
            var methodname = String(m.getEnclosingClass().getPackageName() + "." + m.getEnclosingClass().getName() + "." + m.getName());
            var views = map[methodname];
            if (views === null || views === undefined || views.length == 0) views = [];
            for each (var prefix in page_prefixes) {
                for each (var suffix in page_suffixes) {
                    vn = prefix + viewname + suffix;
                    vn = String(vn).replace(/\/\//g,'/');
                    vn = String(vn).replace(/\\\\/g,'\\');
                    views[views.length] = vn;
                }
            }
            if (isApacheTiles) {
                for each(var atv in getTilesViews(viewname)) {
                    views[views.length] = atv;
                }
            }
            map[methodname] = views;
            methodname_method[methodname] = m;
        }
        var cmethod = controller_methods[methodname];
        if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
    }
}

// Process @ModelAttribute annotated methods
// Last step after processing all other view collecting pieces
var ma_methods = nameTable.getMethodsByLabel("SpringModelAttributeMethod", "java");
if (ma_methods !== null && ma_methods !== undefined) {
    for each (var ma_method in ma_methods) {
        var enc_class = ma_method.getEnclosingClass();
        var ma_methodname = String(enc_class.getPackageName() + "." + enc_class.getName() + "." + ma_method.getName());
        var views = map[ma_methodname];
        if (views === null || views === undefined || views.length == 0) views = [];
        map[ma_methodname] = views;
        methodname_method[ma_methodname] = ma_method;
        for each (var controller_method in enc_class.getMethods()) {
            view_dispatch_method = false;
            for each (var l in controller_method.getLabels()) {
                if (String(l) == "SpringELVisible") {
                    view_dispatch_method = true;
                    break;
                }
            }
            if (view_dispatch_method) {
                var methodname = String(enc_class.getPackageName() + "." + enc_class.getName() + "." + controller_method.getName());
                var cviews = map[methodname];
                if (cviews !== null && cviews !== undefined && cviews.length > 0)
                    map[ma_methodname] = map[ma_methodname].concat(cviews)
            }
        }
    }
}

// Process collected views
// remove duplicated slashes and make sure the view file exists
// set SpringFunctionView:viewPath labels for backend usage
var validviewmap = {};
var allFiles = getAllProgramFileNames();
if (allFiles !== null && allFiles !== undefined) {
    for (var methodname in map) {
        //alert("Found " + String(map[methodname].length) + " possible views for method: " + methodname);
        var validviews = [];
        for each (var viewname in map[methodname]) {
            for each (f in allFiles) {
                if (f !== null && f.indexOf(viewname) > -1) {
                    var m = methodname_method[methodname];
                    m.setLabel("SpringFunctionView::" + f);
                    validviews[validviews.length] = f;
                    //alert("\t\tController method: " + "SpringFunctionView::" + f);
                }
            }
        }
        validviewmap[methodname] = validviews;
    }
}

// Caching unique page objects to inject
var field_map = {};
for each (var m in controller_methods) {
    if (m !== null) {
        var methodname = String(m.getEnclosingClass().getPackageName() + "." + m.getEnclosingClass().getName() + "." + m.getName());
        //alert("Controller method: " + methodname)
        for each (var label in m.getLabels()) {
            if (String(label).match(/SpringELVisible::([.a-zA-Z0-9]*)::([.a-zA-Z0-9]*)/)) {
                var fldname = extractAttributeName(label);
                var fldtype = extractAttributeType(label);
                if (fldname === "SpringConvention") fldname = generateFieldName(fldtype);
                //alert("       " + fldname + " ==== " + fldtype)
                if (fldname !== null) {
                    var cmethod = methodname;
                    var pages = uniq(validviewmap[cmethod]);
                    for each(var f in pages) {
                        var id = f + ":::" + fldname + ":::" + fldtype;
                        if (field_map[id] == undefined) {
                            field_map[id] = [{page: f, name: fldname, type: fldtype, controllermethod: cmethod}];
                        } else {
                            var items = field_map[id];
                            var additem = true;
                            for each (var item in items) {
                                if (item.page == f && item.name == fldname && item.type == fldtype && item.controllermethod == cmethod) {
                                    additem = false;
                                }
                            }
                            if (additem) items[items.length] = {page: f, name: fldname, type: fldtype, controllermethod: cmethod};
                            field_map[id] = items;
                        }
                    }
                }
            }
        }
    }
}
for each (var fieldlist in field_map) {
    for each (var field in fieldlist) {
        //alert("[+] Calling addFieldToFrameworkVisibilityTypeOfPage(\"" + field.page + "\", \"" + field.name + "\", \"" + field.type + "\", \"" + field.controllermethod + "\");");
        addFieldToFrameworkVisibilityTypeOfPage(field.page, field.name, field.type, field.controllermethod);
    }
}

//alert(" $$$$$$$$$  In hibernateLabeling ##########");
var hibernate_config_entities = loadPersistedObject("program.hibernate_config_entities");

if (hibernate_config_entities != null) {
//alert ("Got hibernate_config_entities for labeling");
}

for each (var hibernateEntity in hibernate_config_entities) {
  if (hibernateEntity.hasPackage) {
    if (String(hibernateEntity.cls).lastIndexOf(".") > -1) {
        var he = splitFullyQualifiedClsName(hibernateEntity.cls);
        var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
        if (beanClass != null && '[UnknownType]' != beanClass.getName()) {
            beanClass.setLabel("hibernateEntity");
        }
    } else {
        var beanClass = nameTable.getClassByName(hibernateEntity.pkg, hibernateEntity.cls, "java");
        if (beanClass != null && '[UnknownType]' != beanClass.getName()) {
            beanClass.setLabel("hibernateEntity");
        }
    }
    //alert("Labeled Hibernate Entity" + hibernateEntity.pkg + "." + hibernateEntity.cls);
  } else {
    var he = splitFullyQualifiedClsName(hibernateEntity.cls);
    var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
    if (beanClass != null && '[UnknownType]' != beanClass.getName()) {
        beanClass.setLabel("hibernateEntity");
    }
    //alert("Labeled Hibernate Entity" +  hibernateEntity.cls);
  }
}

        //
        // Set up data structures for struts beans
        //
        function init_struts1() {
          var ns = new Namespace("");
          var beanCount = 0;
          var actionCount = 0;
          program.val_files = null;
          program.form_beans = new Array();
          program.struts1_actions = new Array();
          program.validation_forms = new Array();
          program.struts1_val_files = new Array();
          dbg("in struts1_config");
          for (var cfg in program.xml) {
            dbg("interating over program.xml");
            // look at struts-config.xml
            if (null != program.xml[cfg].name() && null != program.xml[cfg].name().localName.match("struts-config")) {
              dbg("found struts-config");
              for each (var j in program.xml[cfg]..ns::["form-bean"]) {
                dbg("iterating over form beans");
                var thisBean = new Object();
                thisBean.name = String(j["@name"]);
                thisBean.clss =  String(j["@type"]);
                thisBean.properties = new Array();
                thisBean.property_details = new Array();
                thisBean.fields = new Array();
