        var fields = action_form.getFields();
        var methods = action_form.getMethods();
        for each (var field in fields) {
            var getter = "get" + field.getName().toLowerCase();
            var setter = "set" + field.getName().toLowerCase();
            has_setter = has_getter = false;
            for each (var method in methods) {
                if (getter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                    has_getter = true;
                }
                if (setter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                    has_setter = true;
                }
            }
            if (has_setter && has_getter) {
                processField(field, visited);
            }
        }
    }
}
