// Struts 2
function processAction(action, visited) {
    if (action !== null && action !== undefined && action != "[UnknownType]") {
        var fields = action.getFields();
        var methods = action.getMethods();
        for each (var field in fields) {
            var getter = "get" + field.getName().toLowerCase();
            var setter = "set" + field.getName().toLowerCase();
            has_setter = has_getter = false;
            for each (var method in methods) {
                if (getter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                    has_getter = true;
                }
                if (setter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                    has_setter = true;
                }
            }
            if (has_setter && has_getter) {
                processField(field, visited);
            }
        }
    }
}

var visited = {};
if (null != program.struts_actions) {
    // Actions defined in configuration files
    for each (var action_obj in program.struts_actions) {
        var action = nameTable.getClassByName(action_obj.namespaceName, action_obj.className, "java");
        processAction(action, visited);
    }
}
var actions = nameTable.getClassesByLabel("Struts2Action", "java");
if (null != actions) {
