/**
*  issues found when equality checks with toUpperCase()/toLowerCase() without using a locale may be got around due to locale.
*  if the defaultLocale is ever set, we assume that this is correct and delete all the issues
*/
function cleanupLocaleIssues(vuln, ruleid, possiblyDeleteList, defaultLocale){
    /* if defaultLocale already found, just delete anything already in list, and delete any vulns matching one of the rule IDs */
    if (defaultLocale === true){
        for each (var vuln in possiblyDeleteList){
            vuln.remove();
        }
        if (ruleid == "D8E9ED3B-22EC-4CBA-98C8-7C67F73CCF4C" || ruleid == "6C9922D7-1DFD-4EE4-AA01-7D7613938577"){
            vuln.remove();
        }
    }else{
        /* if defaultLocale not already found, try to see if it can be, and add to possibleDeleteList */
        if (ruleid == "D8E9ED3B-22EC-4CBA-98C8-7C67F73CCF4C"){
            dbg("adding to list IID: " + vuln.getInstanceIdentifier());
            possiblyDeleteList.push(vuln);
        }else if (ruleid == "6C9922D7-1DFD-4EE4-AA01-7D7613938577"){
            dbg("Found locale default set programmatically");
            defaultLocale = true;
            vuln.remove();
        }
    }
    return defaultLocale;
}

function cleanup(){
    var vulns = getVulnerabilities();
    var localeDependentIssues = new Array();
    var defaultLocale = false;

    for each (var vuln in vulns){
        var ruleid = vuln.getRule().getIdentifier();
        if (ruleid !== undefined && ruleid !== null){
            defaultLocale = cleanupLocaleIssues(vuln, ruleid, localeDependentIssues, defaultLocale);
        }
    }
}

