function traverseSuperClasses(clss, clssName, bean) {
  // I don't think we want to check for '[UnknownType]' == clss.getName() because this will break recursion
  if (null == clss) {
return;
  }

  dbg("clssName: " + clssName);
  if (clssName == "org.apache.struts.validator.ValidatorForm" ||
  clssName == "org.apache.struts.validator.ValidatorActionForm" ||
  clssName == "org.apache.struts.validator.DynaValidatorForm" ||
  clssName == "org.apache.struts.validator.DynaValidatorActionForm") {
determineFormKind(bean.clss, bean);
return;
  }
  else if (clssName != "org.apache.struts.action.ActionForm" && clssName != "org.apache.struts.action.DynaActionForm") {
var superClasses = clss.getSuperClasses();

if (null == superClasses || 0 == superClasses.length) {
  return;
}

for each (var superC in superClasses) {
  if (null == superC.getPackageName() || 0 == superC.getPackageName().length) {
    fullName = superC.getName();
  }
  else {
    fullName = superC.getPackageName() + "." + superC.getName();
  }
  dbg("fullName: " + fullName);
  determineFormKind(fullName, bean);
  addFields(superC, fullName, bean);
  traverseSuperClasses(superC, fullName, bean);
}
  }
}

function determineFormKind(className, bean) {
  if (className == "org.apache.struts.validator.ValidatorForm") {
bean.vf = true;
dbg("bean.vf: " + bean.vf);
  }
  else if (className == "org.apache.struts.validator.ValidatorActionForm") {
bean.vf = true;
bean.vaf = true;
dbg("bean.vaf: " + bean.vaf);
  }
  else if (className == "org.apache.struts.validator.DynaValidatorForm") {
bean.dvf = true;
dbg("bean.dvf: " + bean.dvf);
  }
  else if (className == "org.apache.struts.validator.DynaValidatorActionForm") {
bean.dvf = true;
bean.dvaf = true;
dbg("bean.dvaf: " + bean.dvaf);
  }
}

function addFields(clss, className, bean) {
  var field = "";
  var methods = null;
  if (null != clss && '[UnknownType]' != clss.getName()) {
methods = clss.getMethods();
if (null != methods) {
  for each (var m in methods) {
    dbg("method name: " + m.getName());
    if (null != m && null != m.getName().match(/^set.*/)) {
      field = m.getName().substr(3, 1).toLowerCase() + m.getName().substr(4);
      dbg("addField method: " + m.getName());
      dbg("addField field: " + field);
      var thisField = new Object();
      thisField.fieldName = field;
      thisField.className = className;
      bean.fields[bean.fields.length] = thisField;
      dbg("adding to bean.fields: " + thisField.className + "." + thisField.fieldName);
    }
  }
}
  }
}

