                        //
                        // Set up data structures for managed beans.  This handles both JSF and
                        // Spring managed bean configuration files.
                        //
                        function setUpManagedBeans() {
                          var jsfns1 = new Namespace("");                                              // handle JSF < 1.2
                          var jsfns2 = new Namespace("http://java.sun.com/xml/ns/javaee");             // handle JSF >= 1.2
                          var jsfns3 = new Namespace("http://java.sun.com/xml/JSF/Configuration");     // handle another JSF faces namespace
                          var jsfns4 = new Namespace("http://xmlns.jcp.org/xml/ns/javaee");     // handle JSF 2.2 faces namespace
                          var springns = new Namespace("http://www.springframework.org/schema/beans"); // handle spring beans that work with JSF
                          var adfns = new Namespace("http://xmlns.oracle.com/adf/controller");         // handle Oracle ADF
                          var dir_group = new Object(), groups = new Array;
                          var group;
                          var sep = null;
                          var found;

                          // (local function)
                          function processAnnotations(annotation, clss, beanNameFn, beanClassNameFn) {
                            var beans = new Array();
                            var beanName = String(beanNameFn(annotation));
                            var beanClassName = String(beanClassNameFn(clss));
                            if (beanName == "" || beanClassName == "") {
                                dbg("Invalid managed-bean element: Empty bean name or class");
                                return;
                            }
                            if (isValidJavaPackageName(beanClassName)) {
                                var bean = new Object();
                                bean.beanName = beanName;
                                bean.beanClassName = beanClassName;
                                beans[beans.length] = bean;
                                var beanClass = nameTable.getClassByName("", beanClassName, "java");
                                if (isSafeForJavaGlobal(beanClass) && beanClass != null && '[UnknownType]' != beanClass.getName()) {
                                  dbg("Labeling class " + beanClass.getPackageName() + '.' + beanClass.getName());
                                  beanClass.setLabel("ManagedBeanClass");
                                }
                            }
                            // We dont have config files to group beans together. All the beans resolution
                            // coming from annotated manged bean classes are grouped under dir "/"
                            var dir = "/";
                            if (dir_group[dir] == null) {
                                group = new Object();
                                group.dir = dir;
                                group.files = new Array();
                                group.beans = beans;
                                dir_group[dir] = group;
                                groups[groups.length] = group;
                            } else {
                                dir_group[dir].beans = dir_group[dir].beans.concat(beans);
                            }
                          }

                          // (local function)
                          function processDecls(cfgfile, decls, beanNameFn, beanClassNameFn) {
                                var beans = new Array();
                                var pos, pos1, dir;

                                for each (var decl in decls) {
                                  var beanName = String(beanNameFn(decl));
                                  var beanClassName = String(beanClassNameFn(decl));
dbg("Found " + beanName + " -> " + beanClassName);
                                  if (beanName == "" || beanClassName == "") {
                                        dbg("Invalid managed-bean element: Empty bean name or class in " + decl);
                                        continue;
                                  }
                                  if (isValidJavaPackageName(beanClassName)) {
                                        var bean = new Object();
                                        bean.beanName = beanName;
                                        bean.beanClassName = beanClassName;
                                        beans[beans.length] = bean;
                                        var beanClass = nameTable.getClassByName("", beanClassName, "java");
                                        if (beanClass != null && '[UnknownType]' != beanClass.getName()) {
                                          beanClass.setLabel("ManagedBeanClass");
                                        }
                                  }
                                }
                                // The applicable containing directory is (we hope) the one containing
                                // the WEB-INF directory.
                                pos = cfgfile.lastIndexOf(sep);
                                do {
                                  pos1 = pos;
                                  pos = cfgfile.lastIndexOf(sep, pos - 1);
                                } while (pos > 0 && cfgfile.substring(pos + 1, pos1) != "WEB-INF");
                                if (pos <= 0) {
                                  log("\"WEB-INF\" not found in \"" + cfgfile + "\"");
                                } else {
                                  dir = cfgfile.substring(0, pos);
dbg("Dir: " + dir);
                                  if (dir_group[dir] == null) {
                                        group = new Object();
                                        group.dir = dir;
                                        group.files = new Array();
                                        group.beans = beans;
                                        dir_group[dir] = group;
                                        groups[groups.length] = group;
                                  } else {
                                        dir_group[dir].beans = dir_group[dir].beans.concat(beans);
                                  }
                                }
                          }

                          var springJSFIntegration = false;
                          // First, collect the bean declarations from the config files, organizing
                          // them by the directory containing the config file.
                          for (var cfgfile in program.xml) {
                                var cfg = program.xml[cfgfile];
                                if (sep == null) {
                                  if (cfgfile[1] == ":" && cfgfile[2] == "\\") sep = "\\";
                                  else sep = "/";
                                }
                                if (cfg.name() == null ||
                                        // Ignore files that arent under a WEB-INF directory
                                        cfgfile.indexOf(sep + "WEB-INF" + sep) < 0) {
                                  continue;
                                }
                                dbg("Looking at " + cfgfile);
                                dbg("NS " + cfg.name().uri);
                                dbg("LN " + cfg.name().localName);
                                if (cfg.name().uri == jsfns1.uri && cfg.name().localName == "faces-config") {
                                    for each(var elresolver in cfg..jsfns1::["el-resolver"]) {
                                        if (elresolver !== null && elresolver !== undefined) {
                                            if (elresolver.text() == "org.springframework.web.jsf.el.SpringBeanFacesELResolver") {
                                                springJSFIntegration = true;
                                                break;
                                            }
                                        }
                                    }
                                    processDecls(cfgfile, cfg..jsfns1::["managed-bean"],
                                                           function (decl) { return decl..jsfns1::["managed-bean-name"]; },
                                                           function (decl) { return decl..jsfns1::["managed-bean-class"]; });
                                } else if (cfg.name().uri == jsfns2.uri && cfg.name().localName == "faces-config") {
                                    for each(var elresolver in cfg..jsfns2::["el-resolver"]) {
                                        if (elresolver !== null && elresolver !== undefined) {
                                            if (elresolver.text() == "org.springframework.web.jsf.el.SpringBeanFacesELResolver") {
                                                springJSFIntegration = true;
                                                break;
                                            }
                                        }
                                    }
                                    processDecls(cfgfile, cfg..jsfns2::["managed-bean"],
                                                           function (decl) { return decl..jsfns2::["managed-bean-name"]; },
                                                           function (decl) { return decl..jsfns2::["managed-bean-class"]; });
                                } else if (cfg.name().uri == jsfns3.uri && cfg.name().localName == "faces-config") {
                                    for each(var elresolver in cfg..jsfns3::["el-resolver"]) {
                                        if (elresolver !== null && elresolver !== undefined) {
                                            if (elresolver.text() == "org.springframework.web.jsf.el.SpringBeanFacesELResolver") {
                                                springJSFIntegration = true;
                                                break;
                                            }
                                        }
                                    }
                                    processDecls(cfgfile, cfg..jsfns3::["managed-bean"],
                                                           function (decl) { return decl..jsfns3::["managed-bean-name"]; },
                                                           function (decl) { return decl..jsfns3::["managed-bean-class"]; });
                                } else if (cfg.name().uri == jsfns4.uri && cfg.name().localName == "faces-config") {
                                    for each(var elresolver in cfg..jsfns4::["el-resolver"]) {
                                        if (elresolver !== null && elresolver !== undefined) {
                                            if (elresolver.text() == "org.springframework.web.jsf.el.SpringBeanFacesELResolver") {
                                                springJSFIntegration = true;
                                                break;
                                            }
                                        }
                                    }
                                    processDecls(cfgfile, cfg..jsfns4::["managed-bean"],
                                                           function (decl) { return decl..jsfns4::["managed-bean-name"]; },
                                                           function (decl) { return decl..jsfns4::["managed-bean-class"]; });
                                }
                                if (cfg.name().uri == adfns.uri && cfg.name().localName == "adfc-config") {
                                    processDecls(cfgfile, cfg..adfns::["managed-bean"],
                                                           function (decl) { return decl..adfns::["managed-bean-name"]; },
                                                           function (decl) { return decl..adfns::["managed-bean-class"]; });
                                }
                                if (springJSFIntegration && cfg.name().uri == springns.uri && cfg.name().localName == "beans") {
                                    processDecls(cfgfile, cfg..springns::["bean"],
                                                           function (decl) {
                                                        var id = decl.attribute("id");
                                                        if (String(id) == "") id = decl.attribute("name");
                                                        return id;
                                                       },
                                                       function (decl) { return decl.attribute("class"); });
                                  // Local function to handle nested imports.  Since we don't bother to figure
                                  // out which is the root config file, we can wind up processing leaf files
                                  // more than once, but no harm is done thereby.
                                  function processImports(cfgroot) {
                                        for each (var importelt in cfgroot..springns::["import"]) {
                                          var dir = cfgfile;
                                          var importfile = String(importelt.attribute("resource"));
                                          // strip basename, leaving directory
                                          dir = dir.substring(0, dir.lastIndexOf(sep));
                                          if (importfile.indexOf("file:") == 0) {
                                                importfile = importfile.substring(5);
                                          } else if (importfile.indexOf("classpath:") == 0) {
                                                log("Can't resolve classpath import resource: " + importfile);
                                                continue;
                                          } else {
                                                // Leading slash is ignored (per Spring docs)
                                                if (importfile.charAt(0) == "/") {
                                                  importfile = importfile.substring(1);
                                                }
                                                // It's common for these paths to start with one or more ".." elements
                                                while (importfile.indexOf("../") == 0) {
                                                  importfile = importfile.substring(3);
                                                  dir = dir.substring(0, dir.lastIndexOf(sep));
                                                }
                                                if (sep == "\\") {
                                                  importfile = importfile.replace(/\//g, "\\");
                                                }
                                                importfile = dir + sep + importfile;
                                          }
dbg("Import: " + importfile);
                                          var imported = program.xml[importfile];
                                          if (imported == null) {
                                                setUpCaseInsensitiveXmlFileMap();
                                                imported = program.xml_ci[importfile.toLowerCase()];
                                          }
                                          if (imported == null) {
                                                log("Can't find Spring bean import file [" + importfile + "]");
                                          } else {
                                                processDecls(cfgfile, imported..springns::["bean"],
                                                                         function (decl) { return decl.attribute("id"); },
                                                                         function (decl) { return decl.attribute("class"); });
                                                processImports(imported);
                                          }
                                        }
                                  }

                                  processImports(cfg);
                                }
                          }

                          // and collect the bean declarations from the annotated managed bean classes files
                          var allClasses = nameTable.getAllClasses("java");
                          var ann;
                          for each (var clss in allClasses) {
                              if (clss != null) {

                                  // Helper functions
                                  var beanNameFnName = function (annotation) {
                                              var nameProp = annotation.get("name");
                                              if (nameProp == null) {
                                                  // Bean name is set by the framework as the class name with the first letter lowercase
                                                  beanName = clss.getName().substr(0,1).toLowerCase() + clss.getName().substr(1);
                                              } else {
                                                  // Bean name is set by the developer through the annotation
                                                  beanName = nameProp.getStrValue();
                                              }
                                              return beanName;
                                          };
                                  var beanNameFnValue = function (annotation) {
                                              var nameProp = annotation.get("value");
                                              if (nameProp == null) {
                                                  // Bean name is set by the framework as the class name with the first letter lowercase
                                                  beanName = clss.getName().substr(0,1).toLowerCase() + clss.getName().substr(1);
                                              } else {
                                                  // Bean name is set by the developer through the annotation
                                                  beanName = nameProp.getStrValue();
                                              }
                                              return beanName;
                                          };
                                  var beanClassFn = function (clss) { return clss.getPackageName() + "." +  clss.getName();};
                                  // JSF2 @ManagedBean annotated beans
                                  ann = clss.getAnnotation("javax.faces.bean.ManagedBean");
                                  if (ann != null) {
                                      processAnnotations(ann, clss, beanNameFnName, beanClassFn);
                                  }
                                  // JSR330 @Named annotated beans
                                  ann = clss.getAnnotation("javax.inject.Named");
                                  if (ann != null) {
                                      processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                  }
                                  // JSR @javax.annotation.ManagedBean annotated beans
                                  ann = clss.getAnnotation("javax.annotation.ManagedBean");
                                  if (ann != null) {
                                      processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                  }
                                  // Spring beans in case JSF/Spring integration is enabled
                                  if (springJSFIntegration) {
                                    // Spring @Component annotated beans
                                    ann = clss.getAnnotation("org.springframework.stereotype.Component");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                    // Spring @Repository annotated beans
                                    ann = clss.getAnnotation("org.springframework.stereotype.Repository");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                    // Spring @Service annotated beans
                                    ann = clss.getAnnotation("org.springframework.stereotype.Service");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                    // Spring @Controller annotated beans
                                    ann = clss.getAnnotation("org.springframework.stereotype.Controller");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                    // Spring @RestController annotated beans
                                    ann = clss.getAnnotation("org.springframework.web.bind.annotation.RestController");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                  }
                              }
                          }


                          // Second, sort the groups into decreasing order by directory (decreasing so
                          // that in case any of them are nested (which they really shouldn't be anyway)
                          // we try the deeper ones first).
                          groups.sort(function (g1, g2) {
                                                        if (g2.dir < g1.dir) return -1;
                                                        else if (g2.dir > g1.dir) return 1;
                                                        else return 0;
                                                  });
                          // Third, collect the JSP/JSPX/XHTML files in each group.
                          for each (var file in getJSPFileNames()) {
                                for each (var g in groups) {
                                  found = false;
                                  if (file.indexOf(g.dir) == 0) {
                                        g.files[g.files.length] = file;
                                        found = true;
                                        // let the groups share the same files
                                        // break;
                                  }
                                  if (!found) log("Can't find config file for [" + file + "]");
                                }
                          }
                          // Finally, pass the data back to the analyzer.  Alas, we have to do it
                          // this way -- we can't just pass the whole data structure.
                          openManagedBeanMap();
                          for (var i = 0; i < groups.length; ++i) {
                                group = groups[i];
                                newManagedBeanSubmap();
                                for (var j = 0; j < group.beans.length; ++j) {
                                  addManagedBeanSubmapPair(group.beans[j].beanName, group.beans[j].beanClassName);
                                }
                                for (var j = 0; j < group.files.length; ++j) {
                                  addManagedBeanFile(group.files[j]);
                                }
                          }
                          closeManagedBeanMap();
                        }

                        function setUpCaseInsensitiveXmlFileMap() {
                          if (program.xml_ci == null) {
                                program.xml_ci = new Object();
                                for (var fn in program.xml) {
                                  program.xml_ci[fn.toLowerCase()] = program.xml[fn];
                                }
                          }
                        }

                        if (!program.managed_beans_set_up) {
                          setUpManagedBeans();
                          program.managed_beans_set_up = true;
                        }

        //
        // Set up data structures for JSF beans used for storing user input
        //

        if (null == program.jsf_beans) {
//dbg("java: INITIALIZING JSF");
          program.jsf_beans = new Array();
          var urlInfo = null;
          var navRules = new Array();
          var jsfBeanCount = 0;
          collectJSFBeans("");                                   // handle JSF pre 1.2
          collectJSFBeans("http://java.sun.com/xml/ns/javaee");  // handle JSF 1.2
          collectJSFBeans("http://xmlns.jcp.org/xml/ns/javaee");     // handle JSF 2.2
        }
        else {
//dbg("java: JSF HAS ALREADY BEEN INITIALIZED");
        }

        if (null == program.jsfInputs || null == program.jsfPrivateInputs) {
//dbg("java: INITIALIZING JSF INPUTS AND SOURCES");
          program.jsfInputs = new Array();                     // contains JSF input tags info
          program.jsfPrivateInputs = new Array();              // ciontains JSF password tags info
          collectInputs("");                                   // handle JSF pre 1.2
          collectInputs("http://java.sun.com/xml/ns/javaee");  // handle JSF 1.2
          collectInputs("http://xmlns.jcp.org/xml/ns/javaee");  // handle JSF 2.2
          default xml namespace = new Namespace("xmlns://www.fortifysoftware.com/schema/rules");
        }
        else {
//dbg("java: JSF INPUTS AND SOURCES HAVE ALREADY BEEN INITIALIZED");
        }

        //
        // Set up data structures for JSF managed beans
        //
        function collectJSFBeans(defaultJSFNamespace) {
          default xml namespace = new Namespace(defaultJSFNamespace);
          var ns = new Namespace(defaultJSFNamespace);

          for each (var cfg in program.xml) {
//dbg("in outer loop: " + cfg.name());
            if (null == cfg.name() || null == cfg.name().localName.match("faces-")) {
              continue;
            }

            // depending on the version, web.xml either uses default namespace or http://java.sun.com/xml/ns/j2ee
            urlInfo = getURLExtensionFromServletMapping("", "javax.faces.webapp.FacesServlet");
            if (null == urlInfo) {
              urlInfo = getURLExtensionFromServletMapping("http://java.sun.com/xml/ns/j2ee", "javax.faces.webapp.FacesServlet");
            }
            if (null == urlInfo) {
              urlInfo = getURLExtensionFromServletMapping("http://xmlns.jcp.org/xml/ns/j2ee", "javax.faces.webapp.FacesServlet");
            }

//dbg("in outer loop after if");

            for each (var j in cfg..ns::["navigation-rule"]) {
              var from = String(j["from-view-id"]);
//dbg("from: " + from);
              var to = new Array();
              for each (var c in j..ns::["navigation-case"]) {
                to[to.length] = String(c["to-view-id"]);
//dbg("to: " + String(c["to-view-id"]));
              }
              navRules[from] = to;
            }
          }
        }

        //
        // This function parses #{bean.property} and
        // fills program.jsfInputs array with corresponding values.
        //
        function addJSFInputs(datastructure, inputValue, jspFileName, jspFormId, jspFormLineNumber) {
            //dbg("Adding JSF Input (file: "+jspFileName+" (line: "+jspFormLineNumber+") input value: "+inputValue);
            var thisInput = new Object();
            var temp = String(inputValue); // manually convert this to a string, so it works on windows
            thisInput.el = temp;
            thisInput.filename = jspFileName;
            thisInput.formid = jspFormId;
            thisInput.formlinenumber = jspFormLineNumber;
            thisInput.urls = new Array();

            for (var from in navRules) {
                if ("*" == from || -1 != thisInput.filename.indexOf(from)) {
                    thisInput.to = navRules[from];
                }
                if (-1 != thisInput.filename.indexOf(from) && -1 == from.indexOf("*") && 0 != from.length) {
                    thisInput.urls[thisInput.urls.length] = from;
                    dbg("1: " + from);
                } else {
                    for each(var v in navRules[from]) {
                        if (-1 != thisInput.filename.indexOf(v) && -1 == v.indexOf("*") && 0 != v.length) {
                            thisInput.urls[thisInput.urls.length] = v;
                            dbg("2: " + v);
                        }
                    }
                }
            }

            for (var root in urlInfo) {
                if (thisInput.urls.length > 0) {
                    var urls2 = new Array();
                    for (var u in root) {
                        if (-1 != thisInput.filename.search(u) && 0 != u.length) {
                            for each(var url in thisInput.urls) {
                                if (null != url.match(/.*\.jsp$/)) {
                                    var index = url.lastIndexOf(".jsp");
                                    var url2 = url.substring(0, index) + root[u];
                                    urls2[urls2.length] = url2;
                                }
                            }
                        }
                    }
                    if (0 == urls2.length && null != root && null != root[""]) {
                        for each(var url in thisInput.urls) {
                            if (null != url.match(/.*\.jsp$/)) {
                                var index = url.lastIndexOf(".jsp");
                                var url2 = url.substring(0, index) + root[""];
                                urls2[urls2.length] = url2;
                            }
                        }
                    }
                    for each(var i in urls2) {
                        thisInput.urls[thisInput.urls.length] = i;
                        dbg("3: " + i);
                    }
                } else {
                    var url = thisInput.filename;
                    var url2 = thisInput.filename;
                    for (var u in root) {
                        // dbg("u in urlInfo: " + u);
                        if (-1 != url.indexOf(u) && 0 != u.length) {
                            url = url.replace(u, "/");
                            url2 = url;
                            if (null != url.match(/.*\.jsp$/)) {
                                var index = url.lastIndexOf(".jsp");
                                url = url.substring(0, index) + root[u];
                            }
                        }
                    }

                    if (url == url2 && url != thisInput.filename) {
                        thisInput.urls[thisInput.urls.length] = url;
                        dbg("4: " + url);
                    } else if (url != url2 && url != thisInput.filename) {
                        thisInput.urls[thisInput.urls.length] = url;
                        // dbg("5: " + url);
                        thisInput.urls[thisInput.urls.length] = url2;
                        // dbg("6: " + url2);
                    } else if (url == thisInput.filename) {
                        var i = url.lastIndexOf("/");
                        url = url.substring(i + 1);
                        thisInput.urls[thisInput.urls.length] = url;
                        dbg("7: " + url);
                    }
                }
            }


            var beansandprops = getBeansAndProperty(inputValue);

            // getBeansAndProperty() makes sure that the contents of the returned array are valid Java identifiers, so we don't have to do more checks
            if (beansandprops.length > 0) {
                thisInput.bean = beansandprops[0];
                if (2 == beansandprops.length) {
                    // handle #{a.b}
                    thisInput.property = beansandprops[1];
                } else if (1 == beansandprops.length) {
                    // handle #{a}
                    thisInput.property = ".*";
                } else {
                    // handle #{a.b.c}
                    thisInput.property = inputValue;
                }
                datastructure[datastructure.length] = thisInput;
            }
        }

        //
        // This function matches JSF beans with JSF inputs.
        //
        function addJSFSources(inputstructure, labelToUse) {
//dbg("ADDJSFSOURCES");
          for each (var j in program.jsf_beans) {
//dbg("here");
            for each (var i in inputstructure) {
//dbg("in for");
              if (i.bean == j.name) {
//dbg("in if");
                var thisBean = new Object();
                if (-1 != i.property.indexOf("*")) {
                  // handle #{a}
                  thisBean.clss = j.clss;
                  thisBean.functionName = "get" + i.property;
                  thisBean.fieldName = i.property;
                }
                else if (-1 != i.property.indexOf(".")) {
                  // handle #{a.b.c}
                  thisBean.clss = iterateOverNestedProperties(j.clss, i.property);

                  var props = getBeansAndProperty(i.property);

                  // getBeansAndProperty() makes sure that the contents of the returned array are valid Java identifiers, so we don't have to do more checks
                  thisBean.functionName = "get" + props[props.length-1].substr(0, 1).toUpperCase() + props[props.length-1].substr(1);
                  thisBean.fieldName = props[props.length-1];
                }
                else {
                  // handle #{a.b}
                  thisBean.clss = j.clss;
                  thisBean.functionName = "get" + i.property.substr(0, 1).toUpperCase() + i.property.substr(1);
                  thisBean.fieldName = i.property;
                }
                if (null == thisBean.clss || 0 == thisBean.clss.length) {
                  continue;
                }

                i.clss = thisBean.clss;
                i.setter = "set" + thisBean.fieldName.substr(0, 1).toUpperCase() + thisBean.fieldName.substr(1);
              }
            }
          }
        }

        //
        // This function Iterates over all fake xml files, collects information
        // about input tags, matches that information with bean declarations
        // in faces configuration file.

        function collectInputs(defaultJSFNamespace) {
          default xml namespace = new Namespace(defaultJSFNamespace);
          var jsfns = new Namespace("http://java.sun.com/jsf/html");
          var jsfnscore = new Namespace("http://java.sun.com/jsf/core");
          var xhtmlNamespace = new Namespace("http://www.w3.org/1999/xhtml");

          var jsfns22 = new Namespace("http://xmlns.jcp.org/jsf/html");
          var jsfnscore22 = new Namespace("http://xmlns.jcp.org/jsf/core");

      // Iterate through standard JSP files for JSF entries
          for (var jsffile in program.cxml) {
            for each (var f in program.cxml[jsffile]..jsfns::form) {
              var formid = "";
              if (null != f["@id"]) {
                formid = String(f["@id"]) + " ";
              }
              var linenumber = String(f["@__FFY__LOC"]);
              var colonIndex = linenumber.lastIndexOf(":");
              linenumber = linenumber.substring(0, colonIndex);

              for each (var j in f..jsfns::inputText) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns::inputSecret) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
                addJSFInputs(program.jsfPrivateInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns::inputTextarea) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns::inputHidden) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfnscore::selectItem) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
                addJSFInputs(program.jsfInputs, String(j["@itemValue"]), jsffile, formid, linenumber);
                addJSFInputs(program.jsfInputs, String(j["@itemLabel"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfnscore::selectItems) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns::selectManyCheckbox) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns::selectManyListbox) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns::selectManyMenu) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns::selectOneMenu) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns::selectOneListbox) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns::selectOneRadio) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
            }
            for each (var vp in program.cxml[jsffile]..jsfnscore::viewParam) {
                var linenumber = String(vp["@__FFY__LOC"]);
                addJSFInputs(program.jsfInputs, String(vp["@value"]), jsffile, "", linenumber);
            }
            // JSF 2.2 Namespaces
            for each (var f in program.cxml[jsffile]..jsfns22::form) {
              var formid = "";
              if (null != f["@id"]) {
                formid = String(f["@id"]) + " ";
              }
              var linenumber = String(f["@__FFY__LOC"]);
              var colonIndex = linenumber.lastIndexOf(":");
              linenumber = linenumber.substring(0, colonIndex);

              for each (var j in f..jsfns22::inputText) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns22::inputSecret) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
                addJSFInputs(program.jsfPrivateInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns22::inputTextarea) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns22::inputHidden) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfnscore22::selectItem) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
                addJSFInputs(program.jsfInputs, String(j["@itemValue"]), jsffile, formid, linenumber);
                addJSFInputs(program.jsfInputs, String(j["@itemLabel"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfnscore22::selectItems) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns22::selectManyCheckbox) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns22::selectManyListbox) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns22::selectManyMenu) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns22::selectOneMenu) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns22::selectOneListbox) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
              for each (var j in f..jsfns22::selectOneRadio) {
                addJSFInputs(program.jsfInputs, String(j["@value"]), jsffile, formid, linenumber);
              }
            }
            for each (var vp in program.cxml[jsffile]..jsfnscore22::viewParam) {
                var linenumber = String(vp["@__FFY__LOC"]);
                addJSFInputs(program.jsfInputs, String(vp["@value"]), jsffile, "", linenumber);
            }
          }

      // Iterate through standard XHTML files for Facelets' jsfc entries
          for (var XHTMLFile in program.cxml) {
            for each (var f in program.cxml[XHTMLFile]..xhtmlNamespace::form) {
              var formid = "";
              if (null != f["@id"]) {
                formid = String(f["@id"]) + " ";
              }
              var linenumber = String(f["@__FFY__LOC"]);
              var colonIndex = linenumber.lastIndexOf(":");
              linenumber = linenumber.substring(0, colonIndex);

          // dbg("collectInputs: Form ID: "+formid +"; Line Number: "+linenumber+"; Colon Index: "+colonIndex);

          // Examine any elements that have an attribute of 'jsfc'

          // This is a good sample that retrieves all xml elements with jsfc attribute of h:inputText
          // Please ignore this
          // var jsfcElements = f..xhtmlNamespace::*.(@jsfc == "h:inputText");

          // Experimental(returns all attribute values of jsfc)
          // Please ignore this
          // var jsfcElements = f..xhtmlNamespace::*.@jsfc;

          var jsfcElements = f..xhtmlNamespace::*;

          for each (var jsfcElement in jsfcElements) {
          if (jsfcElement.hasOwnProperty("@jsfc")) {
              var rawJsfcAttributeValue = String(jsfcElement["@jsfc"]);
              var jsfcAttributeValue = rawJsfcAttributeValue;

              var rawValueAttributeValue = String(jsfcElement["@value"]);
              var valueAttributeValue = rawValueAttributeValue;

              // Strip off namespace at beginning of jsfc attribute value
              var namespaceSeperatorIndex = rawJsfcAttributeValue.indexOf(":");
              if (namespaceSeperatorIndex != -1) {
              jsfcAttributeValue = rawJsfcAttributeValue.substring(namespaceSeperatorIndex+1, rawJsfcAttributeValue.length);
              }

              switch (jsfcAttributeValue.toLowerCase()) {
              case "inputtext":
              case "inputtextarea":
              case "inputhidden":
                  // dbg("collectInputs: adding to program.jsfInputs [valueAttributeValue="+valueAttributeValue+"; XHTML="+XHTMLFile+"; formid="+formid+"; linenumber="+linenumber+"]");
                  addJSFInputs(program.jsfInputs, valueAttributeValue, XHTMLFile, formid, linenumber);
                  break;

              case "inputsecrect":
                  // dbg("collectInputs: adding to program.jsfInputs [valueAttributeValue="+valueAttributeValue+"; XHTML="+XHTMLFile+"; formid="+formid+"; linenumber="+linenumber+"]");
                  addJSFInputs(program.jsfInputs, valueAttributeValue, XHTMLFile, formid, linenumber);
                          addJSFInputs(program.jsfPrivateInputs, valueAttributeValue, XHTMLFile, formid, linenumber);
                  break;

              case "selectitem":
                  // dbg("collectInputs: adding to program.jsfInputs [valueAttributeValue="+valueAttributeValue+"; XHTML="+XHTMLFile+"; formid="+formid+"; linenumber="+linenumber+"]");
                  var rawItemValueValue = String(jsfcElement["@itemValue"]);
                  var rawitemLabelValue = String(jsfcElement["@itemLabel"]);

                  addJSFInputs(program.jsfInputs, valueAttributeValue, XHTMLFile, formid, linenumber);
                  addJSFInputs(program.jsfInputs, rawItemValueValue, XHTMLFile, formid, linenumber);
                  addJSFInputs(program.jsfInputs, rawitemLabelValue, XHTMLFile, formid, linenumber);
                  break;

              case "selectitems":
              case "selectmanycheckbox":
              case "selectonemenu":
              case "selectonelistbox":
              case "selectoneradio":
                  // dbg("collectInputs: adding to program.jsfInputs [valueAttributeValue="+valueAttributeValue+"; XHTML="+XHTMLFile+"; formid="+formid+"; linenumber="+linenumber+"]");
                  addJSFInputs(program.jsfInputs, valueAttributeValue, XHTMLFile, formid, linenumber);
                  break;

              default:
                // dbg("collectInputs: ignoring [valueAttributeValue="+valueAttributeValue+"; XHTML="+XHTMLFile+"; formid="+formid+"; linenumber="+linenumber+"]");
                break;
              }
          }
          }
            }
          }

          var ns = new Namespace(defaultJSFNamespace);
          addJSFSources(program.jsfInputs, "JSFSource");
          addJSFSources(program.jsfPrivateInputs, "JSFPrivateSource");


      function dbg(msg) {
             //alert(msg);
          }
        }

ScriptDefinitions.Script:
    if (null == program.struts_actions) {
dbg("java: INITIALIZING STRUTS 2");
      init_struts2();
    }
    else {
dbg("java: STRUTS 2 HAS ALREADY BEEN INITIALIZED");
    }

    // struts 2 private inputs
    if (null == program.struts2PrivateInputs) {
dbg("java: INITIALIZING STRUTS INPUTS AND SOURCES");
      program.struts2PrivateInputs = new Array();              // contains struts2 password tags info
      var struts2ns = new Namespace("/struts-tags");
      for (var struts2file in program.cxml) {
        for each (var j in program.cxml[struts2file]..struts2ns::form) {
          var formid = "";
          if (null != j["@id"]) {
        formid = String(j["@id"]) + " ";
          }
          else if (null != j["@name"]) {
        formid = String(j["@name"] + " ");
          }

          var linenumber = String(j["@__FFY__LOC"]);
          var colonIndex = linenumber.lastIndexOf(":");
          linenumber = linenumber.substring(0, colonIndex);

          var thisForm = new Object();
          thisForm.formid = formid;
          thisForm.formlinenumber = linenumber;
          thisForm.filename = struts2file;

          // enumerate the forms that submit to struts actions
          if (null != program && null != program.struts_actions) {
        var thisAction = program.struts_actions[String(j["@action"])];
        if (null != thisAction && null != thisAction.actionForms) {
          thisAction.actionForms[struts2file] = thisForm;
        }
          }

          for each (var k in j.struts2ns::password) {
        addStruts2Inputs(program.struts2PrivateInputs, String(j["@action"]), String(k["@name"]));
          }
        }
      }

      addStruts2Sources(program.struts2PrivateInputs);
    }
    else {
dbg("java: STRUTS INPUTS AND SOURCES HAVE ALREADY BEEN INITIALIZED");
    }

            // struts 2 hidden inputs
            if (null == program.struts2HiddenInputs) {
    dbg("java: INITIALIZING STRUTS HIDDEN INPUTS AND SOURCES");
              program.struts2HiddenInputs = new Array();              // contains struts2 hidden tags info
              var struts2ns = new Namespace("/struts-tags");

              for (var struts2file in program.cxml) {
                for each (var j in program.cxml[struts2file]..struts2ns::form) {
                  var formid = "";
                  if (null != j["@id"]) {
                    formid = String(j["@id"]) + " ";
                  }
                  else if (null != j["@name"]) {
                    formid = String(j["@name"] + " ");
                  }

                  var linenumber = String(j["@__FFY__LOC"]);
                  var colonIndex = linenumber.lastIndexOf(":");
                  linenumber = linenumber.substring(0, colonIndex);

                  var thisForm = new Object();
                  thisForm.formid = formid;
                  thisForm.formlinenumber = linenumber;
                  thisForm.filename = struts2file;

                  // enumerate the forms that submit to struts actions
                  if (null != program && null != program.struts_actions) {
                    var thisAction = program.struts_actions[String(j["@action"])];
                    if (null != thisAction && null != thisAction.actionForms) {
                      thisAction.actionForms[struts2file] = thisForm;
                    }
                  }

                  for each (var k in j..struts2ns::hidden) {
                    if (String(k["@key"]).length > 0) {
                        var dotIndex = String(k["@key"]).indexOf(".");
                        if (dotIndex > 0) {
                          var property = String(k["@key"]).substring(0, dotIndex);
                          addStruts2Inputs(program.struts2HiddenInputs, String(j["@action"]), property);
                        }
                        else {
                          addStruts2Inputs(program.struts2HiddenInputs, String(j["@action"]), String(k["@key"]));
                        }
                    } else if (String(k["@name"]).length > 0) {
                        var dotIndex = String(k["@name"]).indexOf(".");
                        if (dotIndex > 0) {
                          var property = String(k["@name"]).substring(0, dotIndex);
                          addStruts2Inputs(program.struts2HiddenInputs, String(j["@action"]), property);
                        }
                        else {
                          addStruts2Inputs(program.struts2HiddenInputs, String(j["@action"]), String(k["@name"]));
                        }
                    }
                  }

                }
              }

              addStruts2HiddenSources(program.struts2HiddenInputs);
            }
            else {
    dbg("java: STRUTS INPUTS AND SOURCES HAVE ALREADY BEEN INITIALIZED");
            }


    //
    // Set up data structures for struts beans and actions
    //
    function init_struts2() {
      var ns = new Namespace("");
      program.struts_actions = new Array();
      for each (var cfg in program.xml) {
dbg("in first for");
        if (cfg.name() != "struts") {
          continue;
        }

        // depending on the version, web.xml either uses default namespace or http://java.sun.com/xml/ns/j2ee
        var actionExtensions = getURLExtensionFromFilterMapping("", "org.apache.struts2.dispatcher.FilterDispatcher");
        if (0 == actionExtensions.length) {
          actionExtensions = getURLExtensionFromFilterMapping("http://java.sun.com/xml/ns/j2ee", "org.apache.struts2.dispatcher.FilterDispatcher");
        }
        if (0 == actionExtensions.length) {
          actionExtensions = getURLExtensionFromFilterMapping("http://xmlns.jcp.org/xml/ns/j2ee", "org.apache.struts2.dispatcher.FilterDispatcher");
        }
dbg("actionExtensions: " + actionExtensions.toString());

        for each (var p in cfg..ns::["package"]) {
          var packageNamespace = String(p["@namespace"]);
          if ("/" != packageNamespace) {
        packageNamespace = packageNamespace + "/";
          }
dbg("packageNamespace: " + packageNamespace);
          for each (var k in p..ns::action) {
dbg("in second for");
        var thisAction = new Object();
        thisAction.name = String(k["@name"]);
        thisAction.clss = String(k["@class"]);
        thisAction.actionURLs = new Array();
        var actionURLCount = 0;
        for each (var actionExtension in actionExtensions) {
          thisAction.actionURLs[actionURLCount++] = packageNamespace + thisAction.name + actionExtension;
        }
dbg("actionURLs: " + thisAction.actionURLs.toString());
        var dotIndex = thisAction.clss.lastIndexOf(".");
        thisAction.namespaceName = thisAction.clss.substring(0, dotIndex);
        thisAction.className = thisAction.clss.substr(dotIndex+1);

        thisAction.actionResults = new Array();
        // fill actionForms array in struts2 script
        thisAction.actionForms = new Array();
        for each (var r in k..ns::["result"]) {
          var result = String(r);
          thisAction.actionResults[result] = result;
dbg("result: " + result);
        }

        addLabelToFields(thisAction.namespaceName, thisAction.className, "Struts2Source");

        // make sure we're dealing with valid Java package name
        if (null == k["@class"] || (null != thisAction.clss && isValidJavaPackageName(thisAction.clss))) {
          program.struts_actions[thisAction.name] = thisAction;
        }
          }
        }
      }
    }

    //
    // Set up data structures for struts2 actions that could be used for storing user input
    //
    function addStruts2Inputs(datastructure, struts2action, struts2name) {
      var thisInput = new Object();
      thisInput.action = struts2action;
      thisInput.property = struts2name;


      // make sure we're dealing with valid Java identifier
      if (isValidJavaIdentifier(thisInput.property)) {
        datastructure[datastructure.length] = thisInput;
      }
    }

    function addStruts2Sources(inputstructure) {
      for each (var j in program.struts_actions) {
dbg("here in addStruts2Sources");
        for each (var i in inputstructure) {
dbg("in for in addStruts2Sources");
          if (i.action == j.name) {
dbg("in if in addStruts2Sources");
        var thisSource = new Object();
        thisSource.clss = j.clss;
        thisSource.fieldName = i.property;

        var dotIndex = j.clss.lastIndexOf(".");
        thisSource.namespaceName = j.clss.substring(0, dotIndex);
        thisSource.className = j.clss.substr(dotIndex+1);

        addLabelToField(thisSource.namespaceName, thisSource.className, thisSource.fieldName, "Struts2PrivateSource");
          }
        }
      }
    }

            // Add Struts 2 Hidden Source Labels
            function addStruts2HiddenSources(inputstructure) {
              for each (var j in program.struts_actions) {
    dbg("here in addStruts2HiddenSources");
                for each (var i in inputstructure) {
    dbg("in for in addStruts2HiddenSources");
                  if (i.action == j.name) {
    dbg("in if in addStruts2HiddenSources");
                    var thisSource = new Object();
                    thisSource.clss = j.clss;
                    thisSource.fieldName = i.property;

                    var dotIndex = j.clss.lastIndexOf(".");
                    thisSource.namespaceName = j.clss.substring(0, dotIndex);
                    thisSource.className = j.clss.substr(dotIndex+1);

                    addLabelToField(thisSource.namespaceName, thisSource.className, thisSource.fieldName, "Struts2HiddenSource");
                  }
                }
              }
            }

ScriptDefinitions.ScriptDefinition:
// Spring 4.2.0 defaults as per http://docs.spring.io/spring/docs/current/javadoc-api/org/springframework/web/accept/ContentNegotiationManagerFactoryBean.html
var useJAF = true;
var favorPathExtension = true;
var ignoreAcceptHeader = false;

var ns = new Namespace("http://www.springframework.org/schema/beans");
for each (var cfg in program.xml) {
    if (null == cfg.name() || null == cfg.name().localName.match("beans")) {
        continue;
    }
    for each(var j in cfg..ns::bean) {
        if (String(j['@class']) == "org.springframework.web.accept.ContentNegotiationManagerFactoryBean"){
            for each(var k in j..ns::property) {
                if (String(k['@name']).toLowerCase() == "usejaf" && String(k['@value']).toLowerCase() == "false") useJAF = false;
                if (String(k['@name']).toLowerCase() == "favorpathextension" && String(k['@value']).toLowerCase() == "false") favorPathExtension = false;
                if (String(k['@name']).toLowerCase() == "ignoreacceptheader" && String(k['@value']).toLowerCase() == "true") ignoreAcceptHeader = true;
            }
        }
    }
}
if (!ignoreAcceptHeader || (useJAF && favorPathExtension)) persistObject("program.spring_rfd_config_protection", "false");
else persistObject("program.spring_rfd_config_protection", "true");

var isProtectedInConfig = ("true" == String(loadPersistedObject("program.spring_rfd_config_protection")));
var appReflectsData = false;
var reflectIssues = [];
var mainIssues = [];
var vulns = getVulnerabilities();
for each (var vuln in vulns) {
    var ruleID = String(vuln.getRule().getIdentifier());

    // Main Issues (progrmatically)
    if (ruleID.equals("C299361B-1527-4671-BE97-9BD565C7BACC")) {
        mainIssues[mainIssues.length] = vuln;
    }
    // Main Issues (configuration)
    else if (ruleID.equals("78824315-2286-4004-BD33-C460AE4A0A53")) {
        if (isProtectedInConfig) vuln.remove();
        else mainIssues[mainIssues.length] = vuln;
    }

    // Make sure application reflects data and uses the Content Negotiation
    else if (ruleID.equals("BD7F7957-FB24-4C56-9B41-105407289CD00")) {
        vuln.remove();
        appReflectsData = true;
    }
}

// Remove main issues if application is protected or does not reflect data
if (!appReflectsData) {
    for each (var v in mainIssues) {
        v.remove();
    }
}

                // This script handles the external entry for Spring 3.0 RequestMapping annotation

 var requestMappingSourceIds = new Array(
       "94236098-4C10-41F0-9C2A-27A3919830000",
       "E7BCC3FE-E02C-4199-9F2F-D147483B871E0",
       "A3DE9131-44D1-4DB9-9D3C-F1B479C83C270"
 );

// alert("In spring_requestmapping_url script");
var vulns=getVulnerabilities();

for each (var vuln in vulns)
{

    // alert("Inside the for vuln loop");
    if (vuln) {
        var taintSource = vuln.getTaintSource();
        if (taintSource != null) {
           var ruleID = String(vuln.getSourceRule().getIdentifier());
           // alert("Vuln ruleId:" + ruleID);

       for each (var id in requestMappingSourceIds) {
           // alert("In source id loop:" + id);


       var methodURLexists = false;
       var classURLexists = false;
       var classURLValue = "";
       var methodURLValue = "";
       var externalEntry = "";

               if (ruleID.equals(id))
               {
           // alert("Source Ids match");

       var methodSource = vuln.getSourceEnclosingFunction();
       var methodAnnotation = methodSource.getAnnotation("org.springframework.web.bind.annotation.RequestMapping");

       var methodClass = methodSource.getEnclosingClass();
       var classAnnotation = methodClass.getAnnotation("org.springframework.web.bind.annotation.RequestMapping");

       var filename = taintSource.getFile();
       var linenumber = 1;
       var urlDescriptionTag = "Spring Class Mapping";

       if ( classAnnotation != null ) {
           // alert("Has class annotation");

        var classURL = classAnnotation.get("value")
        if (classURL != null) {
           classURLexists = true;
           classURLValue = classURL.getStrValue();
           // alert("Class Annotation value is:" + classURLValue);
        }
       }

       if ( methodAnnotation != null) {
         // alert("Has method annotation");

        var methodURL = methodAnnotation.get("value")
        if (methodURL != null) {
           methodURLexists = true;
           linenumber = taintSource.getLine() - 1;
           urlDescriptionTag = "Spring Method Mapping";
           methodURLValue = methodURL.getStrValue();
           // alert("Method Annotation value is:" + methodURLValue);
        }
       }

       // add URL as external entry to the vulnerability
       if ( classURLexists || methodURLexists ) {
                       externalEntry = classURLValue + methodURLValue;
           // alert("External entry exists:" + externalEntry);
           vuln.addExternalEntry(urlDescriptionTag, externalEntry, filename, linenumber );
       }

               }  // matching ruleIDs
           } // loop for source id
        } // this is a dataflow issue
    } // if vuln
 } // for each vuln

//
// program.ADF_AMs maps amName to the object that holds info about this AM
//   amName         e.g. StoreServiceAMLocalWeb
//   appName        e.g. oracle.fodemo.storefront.store.service.StoreServiceAM
//   xmlfilename
//   fullclss
//   namespace
//   clss
//   VOs = new Array() of VO Objects (maps Name to VO)
//     Name         e.g. CustomerRegistration
//     ViewObjectName
//     xmlfilename
//     componentfullclss
//     componentnamespace
//     componentclss
//     rowfullclss      e.g oracle.fodemo.storefront.account.queries.CustomerRegistrationVORowImpl
//     rownamespace
//     rowclss
//     ViewAttributes = new Array() of Attribute Objects (maps Name to Attribute)
//       Name       e.g. PrincipalName
//       AliasName      e.g. PRINCIPALNAME
//       EntityUsage
//       EntityAttrName
//     EOs = new Array() of EO Objects (maps Name to EO)
//       Name       e.g. PersonEO
//       Entity
//       xmlfilename
//       rowfullclss    e.g. oracle.fodemo.storefront.entities.PersonEOImpl
//       rownamespace
//       rowclss
//       Attributes = new Array() of Attribute Objects (maps Name to Attribute)
//         Name     e.g. PrincipalName
//         ColumnName   e.g. PRINCIPALNAME
//
// program.ADF_Pages maps pagePath to the object that holds info about the page
//   pageId         e.g. account_basicInformationPageDef
//   pagePath       e.g. /account/basicInformation.jsff
//   fullPagePath           e.g. /home/user/public_html/account/basicInformation.jsff
//   pageDefPath        e.g. oracle.fodemo.storefront.pageDefs.account_basicInformationPageDef
//   Bindings = new Array() of Binding Objects (maps id to the object itself)
//     id           e.g. PrincipalName
//     iterator     e.g. CustomerRegistrationIterator
//     control      e.g. StoreServiceAMDataControl
//     binds        e.g. CustomerRegistration
// program.ADF_Controls maps the name of the AM (amName) to the Control object
//  ctlId           e.g. StoreServiceAMDataControl
//  amName          e.g. StoreServiceAMLocalWeb
//
program.ADF_AMs = new Array();
program.ADF_Pages = new Array();
program.ADF_Controls = new Array();

var adfappns = new Namespace("http://xmlns.oracle.com/adfm/application");
var adfdatans = new Namespace("http://xmlns.oracle.com/adfm/datacontrol");
for (var cfgfile in program.xml) {
  var cfg = new XML(program.xml[cfgfile]);
  if (null != cfg && null != cfg.name() && null != adfappns && cfg.name().uri == adfappns.uri && cfg.name().localName == "Application") {
    for each (var pageMap in cfg..adfappns::pageMap.adfappns::page) {
      var thisPage = new Object();
      thisPage.pageId = String(pageMap["@usageId"]);
      thisPage.pagePath = String(pageMap["@path"]);
      thisPage.pageDefPath = String(cfg..adfappns::pageDefinitionUsages.adfappns::page.(@id == thisPage.pageId)["@path"]);
      dbg("pageId: " + thisPage.pageId);
      dbg("pagePath: " + thisPage.pagePath);
      dbg("pageDefPath: " + thisPage.pageDefPath);
      getInfoAboutThisPage(thisPage);
    }
    for each (var ctl in cfg..adfappns::dataControlUsages.adfdatans::BC4JDataControl) {
      var thisControl = new Object();
      thisControl.ctlId = String(ctl["@id"]);
      thisControl.amName = String(ctl["@Configuration"]);
      dbg("ctlId: " + thisControl.ctlId);
      dbg("amName: " + thisControl.amName);
      program.ADF_Controls[thisControl.amName] = thisControl;
    }
  }
}

var bc4jconfns = new Namespace("http://xmlns.oracle.com/bc4j/configuration");
var bc4jns = new Namespace("http://xmlns.oracle.com/bc4j");
for (var cfgfile in program.xml) {
  for each (var cfg in program.xml[cfgfile]..bc4jconfns::AppModuleConfig) {
    var amName = String(cfg["@name"]);
    var appName = String(cfg["@ApplicationName"]);
    dbg("appName: " + appName);
    dbg("amName: " + amName);
    if (null != appName && 0 != appName.length && null != amName && 0 != amName.length) {
      for (var xmlAMFile in program.xml) {
        dbg("xmlAMFile: " + xmlAMFile);
        if (null != xmlAMFile.match(appName)) {
          dbg("MATCH@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@");
          var AMXML = new XML(program.xml[xmlAMFile]);
          if (null != AMXML) {
            var thisAM = new Object();
            thisAM.amName = amName;
            thisAM.appName = appName;
            thisAM.xmlfilename = xmlAMFile;
            thisAM.fullclss = String(AMXML["@ComponentClass"]);

            // make sure we're dealing with valid Java class name
            if (false == isValidJavaPackageName(thisAM.fullclss)) {
              continue;
            }
            thisAM.namespace = thisAM.fullclss.substr(0, thisAM.fullclss.lastIndexOf("."));
            thisAM.clss = thisAM.fullclss.substr(thisAM.fullclss.lastIndexOf(".") + 1);
            dbg("thisAM.namespace: " + thisAM.namespace);
            dbg("thisAM.clss: " + thisAM.clss);
            thisAM.VOs = new Array();
            for each (var viewUsage in AMXML..bc4jns::ViewUsage) {
              var thisVO = new Object();
              thisVO.Name = String(viewUsage["@Name"]);
              dbg("thisVO.Name: " + thisVO.Name);
              thisVO.ViewObjectName = String(viewUsage["@ViewObjectName"]);
              dbg("thisVO.ViewObjectName: " + thisVO.ViewObjectName);
              for (var anotherXMLFile in program.xml) {
                if (null != anotherXMLFile.match(thisVO.ViewObjectName)) {
                  dbg("another matched: " + anotherXMLFile);
                  //var VOXML = getXMLForFilename(anotherXMLFile);
                  var VOXML = new XML(program.xml[anotherXMLFile]);
                  if (null != VOXML) {
                    thisVO.xmlfilename = anotherXMLFile;
                    thisVO.componentfullclss = String(VOXML["@ComponentClass"]);
                    thisVO.componentnamespace = thisVO.componentfullclss.substr(0, thisVO.componentfullclss.lastIndexOf("."));
                    thisVO.componentclss = thisVO.componentfullclss.substr(thisVO.componentfullclss.lastIndexOf(".") + 1);
                    thisVO.rowfullclss = String(VOXML["@RowClass"]);
                    thisVO.rownamespace = thisVO.rowfullclss.substr(0, thisVO.rowfullclss.lastIndexOf("."));
                    thisVO.rowclss = thisVO.rowfullclss.substr(thisVO.rowfullclss.lastIndexOf(".") + 1);
                    dbg("thisVO.componentnamespace: " + thisVO.componentnamespace);
                    dbg("thisVO.componentclss: " + thisVO.componentclss);
                    dbg("thisVO.rownamespace: " + thisVO.rownamespace);
                    dbg("thisVO.rowclss: " + thisVO.rowclss);

                    // make sure we're dealing with valid Java package and class names
                    if (false == isValidJavaPackageName(thisVO.rownamespace) || false == isValidJavaIdentifier(thisVO.rowclss)) {
                      continue;
                    }

                    thisVO.EOs = new Array();
                    for each (var entityUsage in VOXML..bc4jns::EntityUsage) {
                      var thisEO = new Object();
                      thisEO.Name = String(entityUsage["@Name"]);
                      thisEO.Entity = String(entityUsage["@Entity"]);
                      dbg("thisEO.Name: " + thisEO.Name);
                      dbg("thisEO.Entity: " + thisEO.Entity);
                      for (var yetAnotherXMLFile in program.xml) {
                        if (null != yetAnotherXMLFile.match(thisEO.Entity)) {
                          dbg("yet another matched: " + yetAnotherXMLFile);
                          //var EOXML = getXMLForFilename(yetAnotherXMLFile);
                          var EOXML = new XML(program.xml[yetAnotherXMLFile]);
                          if (null != EOXML) {
                            thisEO.xmlfilename = yetAnotherXMLFile;
                            thisEO.rowfullclss = String(EOXML["@RowClass"]);
                            thisEO.rownamespace = thisEO.rowfullclss.substr(0, thisEO.rowfullclss.lastIndexOf("."));
                            thisEO.rowclss = thisEO.rowfullclss.substr(thisEO.rowfullclss.lastIndexOf(".") + 1);
                            dbg("thisEO.rownamespace: " + thisEO.rownamespace);
                            dbg("thisEO.rowclss: " + thisEO.rowclss);

                            // make sure we're dealing with valid Java package and class names
                            if (false == isValidJavaPackageName(thisEO.rownamespace) || false == isValidJavaIdentifier(thisEO.rowclss)) {
                              continue;
                            }

                            thisEO.Attributes = new Array();
                            for each (var attribute in EOXML..bc4jns::Attribute) {
                              var thisAttribute = new Object();
                              thisAttribute.Name = String(attribute["@Name"]);
                              thisAttribute.ColumnName = String(attribute["@ColumnName"]).replace(/_/g, "");
                              dbg("thisAttribute.Name: " + thisAttribute.Name);
                              dbg("thisAttribute.ColumnName: " + thisAttribute.ColumnName);

                              // make sure we're dealing with valid Java identifier
                              if (isValidJavaIdentifier(thisAttribute.ColumnName)) {
                                thisEO.Attributes[thisAttribute.Name] = thisAttribute;
                              }
                            }
                          }
                        }
                      }
                      thisVO.EOs[thisEO.Name] = thisEO;
                    }

                    thisVO.ViewAttributes = new Array();
                    for each (var viewAttribute in VOXML..bc4jns::ViewAttribute) {
                      var thisAttribute = new Object();
                      thisAttribute.Name = String(viewAttribute["@Name"]);
                      thisAttribute.AliasName = String(viewAttribute["@AliasName"]).replace(/_/g, "");
                      thisAttribute.EntityUsage = String(viewAttribute["@EntityUsage"]);
                      thisAttribute.EntityAttrName = String(viewAttribute["@EntityAttrName"]);

                      // make sure we're dealing with valid Java identifier
                      if (isValidJavaIdentifier(thisAttribute.AliasName)) {
                        thisVO.ViewAttributes[thisAttribute.Name] = thisAttribute;
                      }
                      dbg("thisAttribute.Name: " + thisAttribute.Name);
                      dbg("thisAttribute.AliasName: " + thisAttribute.AliasName);
                      dbg("thisAttribute.EntityUsage: " + thisAttribute.EntityUsage);
                      dbg("thisAttribute.EntityAttrName: " + thisAttribute.EntityAttrName);
                    }
                  }
                }
              }
              thisAM.VOs[thisVO.Name] = thisVO;
            }
            program.ADF_AMs[amName] = thisAM;
          }
        }
      }
    }
  }
}

openManagedBeanMap();
for each (var currentAM in program.ADF_AMs) {
  newManagedBeanSubmap();
  for each (var currentVO in currentAM.VOs) {
    var VOClassType = handleClassLabeling(currentVO.rownamespace, currentVO.rowclss);
    for each (var attribute in currentVO.ViewAttributes) {
      handleFieldLabeling(VOClassType, attribute.AliasName);
      var from = "";
      if (null != attribute.Name && 0 != attribute.Name.length) {
        from = "bindings." + attribute.Name + ".inputValue";
      }
      var to = "";
      if (0 != from.length && null != currentVO.rowfullclss && 0 != currentVO.rowfullclss.length) {
        to = "" + attribute.Name + ":" + currentVO.rowfullclss + "";
      }
      var currentEO = currentVO.EOs[attribute.EntityUsage];
      if (null != currentEO) {
        var EOClassType = handleClassLabeling(currentEO.rownamespace, currentEO.rowclss);
        if (null != currentEO.Attributes) {
          var entityAttribute = currentEO.Attributes[attribute.EntityAttrName];
          if (null != entityAttribute) {
            handleFieldLabeling(EOClassType, entityAttribute.ColumnName);
            var colon = "";
            if (0 != to.length) {
              colon = ":";
            }
            if (null != currentEO.rowfullclss && 0 != currentEO.rowfullclss.length && null != entityAttribute.Name && 0 != entityAttribute.Name.length) {
              to += "" + colon + entityAttribute.Name + ":" + currentEO.rowfullclss + "";
            }
            if (0 != from.length && 0 != to.length) {
              dbg("from: " + from);
              dbg("to: " + to);
              addManagedBeanSubmapPair(from, to);
            }
          }
        }
      }
    }
  }
  var listOfFullPaths = getFullPagePaths(currentAM.amName);
  for (var path in listOfFullPaths) {
    dbg("adding " + path + " to the managed bean file submap");
    addManagedBeanFile(path);
  }
}
closeManagedBeanMap();

function getInfoAboutThisPage(page) {
  var adfuins = new Namespace("http://xmlns.oracle.com/adfm/uimodel");
  for (var pageFile in program.xml) {
    if (null != pageFile.match(page.pageDefPath)) {
      var pageDef = new XML(program.xml[pageFile]);
      page.Bindings = new Array();
      for each (var binding in pageDef..adfuins::bindings.adfuins::attributeValues) {
        var thisBinding = new Object();
        thisBinding.id = String(binding["@id"]);
        thisBinding.iterator = String(binding["@IterBinding"]);
        thisBinding.control = String(pageDef..adfuins::executables.adfuins::iterator.(@id == thisBinding.iterator)["@DataControl"]);
        thisBinding.binds = String(pageDef..adfuins::executables.adfuins::iterator.(@id == thisBinding.iterator)["@Binds"]);
        dbg("thisBinding.id: " + thisBinding.id);
        dbg("thisBinding.iterator: " + thisBinding.iterator);
        dbg("thisBinding.control: " + thisBinding.control);
        dbg("thisBinding.binds: " + thisBinding.binds);
        page.Bindings[thisBinding.id] = thisBinding;
      }
    }
  }
  for (var fullPagePath in program.cxml) {
    if (null != fullPagePath.match(page.pagePath)) {
      page.fullPagePath = fullPagePath;
      dbg("page.fullPagePath: " + page.fullPagePath);
    }
  }
  program.ADF_Pages[page.pagePath] = page;
}

function getFullPagePaths(am) {
  var listOfFullPaths = new Array();
  if (null != am && 0 != am.length) {
    dbg("getFullPagePaths:am: " + am);
    var control = program.ADF_Controls[am];
    if (null != control && null != control.ctlId) {
      for each (var page in program.ADF_Pages) {
        for each (var binding in page.Bindings) {
          if (binding.control == control.ctlId) {
            listOfFullPaths[page.fullPagePath] = true;
            dbg("getFullPagePaths:fullPagePath: " + page.fullPagePath);
          }
        }
      }
    }
  }
  return listOfFullPaths;
}

function handleClassLabeling(namespaceName, className) {
  if (null != namespaceName && null != className && 0 != className.length) {
    var classType = nameTable.getClassByName(namespaceName, className, "java");
    if (null != classType && '[UnknownType]' != classType.getName()) {
      dbg("put label on class: " + classType.getName());
      if (isSafeForJavaGlobal(classType)) classType.setLabel("ADFClass");
    }
    return classType;
  }
  return null;
}

function handleFieldLabeling(classType, fieldName) {
  if (null != classType && null != fieldName) {
    for each (var field in classType.getFields()) {
      if (fieldName == field.getName()) {
        dbg("put label on field: " + field.getName());
        field.setLabel("ADFField");
      }
    }
  }
}

