//
// This function ckecks if a given type is safe to be promoted to Global, specifically for Java
//
function isSafeForJavaGlobal(cls) {
    var regex = /^(android|sun|java(x)?)\./
    var lang = "java";
    var matches = namespaceMatchesRegularExpression(cls, regex, lang);
    // if match found, or if the class is not found, then it's not safe to try and make global
    if (matches || matches == null) return false;
    return true;
}

//
// attempts to figure out if the application is an Android application
//
function isAndroidApp() {
  dbg("in isAndroidApp");
  for each (var filename in getXMLConfigFileNames()) {
    dbg("iterating over getXMLConfigFileNames()");
    if (null != filename) {
      dbg("null != filename");
      var shortName = String(filename).replace(/\\/g, "/");
      shortName = shortName.substring(shortName.lastIndexOf("/")+1);
      dbg("shortName: " + shortName);
      if ("androidmanifest.xml" == shortName.toLowerCase()) {
        dbg("it's an Android app");
        return true;
      }
    }
  }
  return false;
}
function usesCertificatePinning() {
    for (var filename in program.xml) {
        var cfg = program.xml[filename];
        if (null == cfg.name() || "network-security-config" !== String(cfg.name())) continue;

        for each (var domain in cfg.children()) {
            if (domain.name() != "domain-config") continue;
            for each (var trust in domain.children()) {
                if (trust.name() != "trust-anchors") continue;
                for each (var cert in trust.children()) {
                    if (cert.name() == "certificates") return true;
                }
            }

        }
    }
    return false;
}

