function getVulns(vulns, ruleid) {
  dbg("in getVulns");
  var requested = new Array();
  for each (v in vulns) {
    dbg("iterating over vulns");
    if (null != v) {
      dbg("v != null");
      var rule = v.getRule();
      if (null != rule) {
        dbg("null != rule");
        var id = rule.getIdentifier();
        if (null != id && null != ruleid && ruleid == id) {
          dbg("got a rule match: " + id);
          requested[requested.length] = v;
        }
      }
    }
  }
  return requested;
}

function isSubClassHelper(subclass, targetName) {
    var directSupers = subclass.getSuperClasses();
    var found = false;

    if (directSupers == null || directSupers.length == 0)  {
        return false;
    }

    for each (var sup in directSupers) {
        var dsFullName = sup.getPackageName() ? sup.getPackageName() + "." + sup.getName()
                                              : sup.getName();
        if (targetName == dsFullName) {
            return true;
        }
        found = found || isSubClassHelper(sup, targetName);
    }

    return found;
}

//
// Returns a boolean based on whether subName is a descendent class of superName
// subName and superName are both strings expressed as fully qualified class names, e.g., "java.util.List"
//
function isSubClass(subName, superName) {
    var clsIndex = subName.lastIndexOf(".");

    if (clsIndex == -1) {
        return false;
    }

    var subPkgName = subName.substring(0, clsIndex);
    var subClsName = subName.substring(clsIndex+1);
    var subType = nameTable.getClassByName(subPkgName, subClsName, "java");

    if (!subType || subType.getName() == "[UnknownType]") {
        return false;
    }

    return isSubClassHelper(subType, superName);
}

function remove_vulnerabilities( IDs ) {
    // alert("remove_vulnerabilities");
    var vulns = getVulnerabilities();
    for each (var vuln in vulns) {
        var rule = vuln.getRule();
        var ruleID = String(rule.getIdentifier());

        for each (var id in IDs) {
            if(ruleID.equals(id)) {
                //alert("removing: " + id );
                vuln.remove();
                continue;
            }
        }
    }
}

//
// Function check if a string endsWith another string
//
function endsWith(input, check) {
    var foundIndex = String(input).lastIndexOf(check);
    if (foundIndex > -1) {
        //alert(" foundIndex + check.length = "  + foundIndex + " + " + check.length + " = " + (foundIndex + check.length) +
        //  " But input.length = " + String(input).length );
    }
    if (foundIndex == -1 || input == null || input == "") {
        return false;
    } else if ((foundIndex + check.length) == String(input).length) {
        return true;

    } else {
        return false;
    }
}

