var classes = nameTable.getClassesByLabel("JavaMBean", "java");
if (classes !== null && classes !== undefined) {
    for each (var c in classes) {
        var classnames = extractLabelValues(c, "JavaMBean::");
        if (classnames !== null && classnames !== undefined) {
            for each (var cname in classnames)  {
                var beanClass = nameTable.getClassByName("", cname, "java");
                if (beanClass !== null && beanClass !== undefined && beanClass.getName() != "[UnknownType]") {
                    beanClass.setLabel("JMXBean")
                }
            }
        }
    }
}

