var BASE64_TAINT_FLAG = "BASE64_ENCODED"

var base64_config = {
    taintFlag: BASE64_TAINT_FLAG,
    whitelist: true, //if false, undefined or blacklist set to true, it uses the list of categories as a blacklist
    categories: [
        "System Information Leak",
        "Privacy Violation",
        "Trust Boundary Violation",
        "Mass Assignment",
        "Password Management",
        "Insecure Randomness",
        "Denial of Service",
        "Cross-Session Contamination",
        {
            category: "Path Manipulation"
        }
        /*
        {
            category: "category_name",
            subcategory: "subcategory_name" -- if ommitted, matches all
            // considered having something for lower friority on whitelists, such as a csr field, but this is done per vuln, not per path.
        }

        alternatively just specify a category name whereby all subcategories will be included

        Note: it's ok for the categories lists to overlap. i.e. one whitelist/blacklist can contain the same categories. These will be skipped later.
        */
    ]
}

/*
*   filter the vulnerabilities according to blacklist/whitelist filter configurations
*/
function filter_issues(configs, vuln){
    taintPaths = vuln.getTaintPaths();
    for each (taintPath in taintPaths) {
        blacklist_remove = null; //whether should remove according to a blacklist.
        whitelist_keep = null; //whether we should keep it according to a whitelist

        //go through every configuration and decide whether the
        for each (config in configs){
            // if already blacklisted by another config to be removed, skip
            if (blacklist_remove) {
                continue;
            }
            // check if the taintPath contains the associated taintFlag
            if (!isEncoded(taintPath, config.taintFlag)) {
                continue;
            }

            // if a whitelist and we're already keeping via another whitelist, skip
            if (config.whitelist === true && whitelist_keep === true){
                continue;
            }

            var match_found = matchesCategories(config.categories, vuln);
            if (match_found){
                if (config.whitelist === true){
                    whitelist_keep = true; //keep the issue
                    continue;
                }else{
                    //if not whitelist, and the category is found, then blacklist it for removal
                    blacklist_remove = true;
                    continue;
                }
            }else{
                /**
                *  if it's not in the whitelist, make sure to say we don't want to keep it
                *  set blacklist_remove to true. If set whitelist_keep to false, it would mean that this could be overridden by another whitelist.
                *  i.e. if BASE64_ENCODED and URL_ENCODED, if XSS is still possible when +URL_ENCODED, but not when +BASE64_ENCODED, still want to remove even if in URL_ENCODED whitelist.
                */
                if (config.whitelist === true){
                    blacklist_remove = true;
                }
            }

        }
        // if don't keep because of a whitelist, or specifically blacklisted
        if ((whitelist_keep !== null && whitelist_keep !== true) || (blacklist_remove !== null && blacklist_remove === true)){
            //alert("Removing issues under: " + vuln.getRule().getCategory());
            taintPath.removePath();
        }

    }
}
/**
* Check if the particular taintPath contains the specific taintFlag. Generic for extensibility.
*/
function isEncoded(taintPath, taintFlag){
    for each (tf in taintPath.getTaintFlags()){
        if (tf == taintFlag){
            return true;
        }
    }
    return false;
}

/**
*   Goes through a list of categories of either a string or object containing category/subcategory fields to determine if the vulnerability matches
*/
function matchesCategories(categories, vuln){
    //do checks on list of categories
    for each (cat in categories) {
        var category_name = null;
        var subcategory_name = null;

        //check if a string or an object
        if (isString(cat)){
            category_name = cat;
        }else{
            if (cat.category === undefined || cat.category === null) {
                //alert("category not specified whilst filtering by: " + config.taintFlag);
            }else{
                category_name = cat.category;
            }
            if (cat.subcategory !== undefined && cat.subcategory !== null){
                subcategory_name = cat.subcategory;
            }
        }
        var rule = vuln.getRule();
        if (undefined === rule || null === rule){
            //not sure why rule would be null/undefined, but return safely in case.
            return false;
        }
        var rule_category = rule.getCategory();
        var rule_subcategory = rule.getSubcategory();

        if (rule_category == category_name){
            if (subcategory_name === null || rule_subcategory == subcategory_name){
                return true;
            }
        }
    }
    return false;
}


function init() {
    var vulns=getVulnerabilities();
    var configs = new Array();
    // set up list of configurations to whitelist/blacklist
    configs.push(base64_config);
    for each (vuln in vulns){
        filter_issues(configs, vuln);
    }
}

init();

