function debugMsg(msg) {
    //alert(msg);
}

function processHandler(handler, events) {
    var method = "handleRequest";
    if (handler.indexOf("::") > 0) {
        method = handler.split("::")[1];
        handler = handler.split("::")[0];
    }
    var dotIndex = handler.lastIndexOf(".");
    var packageName = handler.substr(0,dotIndex);
    handler = handler.substring(dotIndex + 1);
    var handlerClass = nameTable.getClassByName(packageName, handler, "java");
    if (handlerClass != "[UnknownType]" && handlerClass != undefined  && handlerClass != null) {
        debugMsg("Found handler: " + handlerClass.getPackageName() + "." + handlerClass.getName());
        debugMsg("Searching method: " + method);
        for each (var m in handlerClass.getMethods()) {
            if (method == m.getName()) {
                debugMsg("Labeling: " + m.getEnclosingClass().getName() + "." + m.getName() + " as AWS_Lambda_Handler");
                m.setLabel("AWS_Lambda_Handler")
                setTypeLabels(m, events);
            }
        }
    } else {
        var global_functions = nameTable.getGlobalFunctions("python");
        if (global_functions !== undefined && global_functions !== null && global_functions.length > 0) {
            for each (var func in global_functions) {
                if (packageName == func.getNameSpace() && handler == func.getName()) {
                    debugMsg("Found handler: " + func.getNameSpace() + "." + func.getName());
                    debugMsg("Searching method: " + func);
                    debugMsg("Labeling: " + func.getNameSpace() + "." + func.getName() + " as AWS_Lambda_Handler");
                    func.setLabel("AWS_Lambda_Handler")
                    setTypeLabels(func, events);
                }
            }
        }
    }
}

function setTypeLabels(handler, events) {
    if (events !== undefined && events !== null) {
        if (events.indexOf('S3') > -1) {
            handler.setLabel("AWS_Lambda_S3")
        }
        if (events.indexOf('Api') > -1) {
            handler.setLabel("AWS_Lambda_ApiGateway")
        }
    }
}

var lambdaRe = /Type:['"\s]*AWS::Serverless::Function["'\s]*/g;
var handlerRe = /(\s+)Handler:\s*(.*)/g;
var eventTypeRe = /(\s+)Type:\s*(.*)/g;

var allFiles = getAllProgramFileNames();

for each (var f in allFiles) {
    try {
        if (endsWith(f, ".yaml") || endsWith(f, ".yml")) {
            var fileContent = readFile(f);
            debugMsg("Processing: " + f)
            if (fileContent.match(lambdaRe)) {
                var lines = fileContent.split("\n");
                var currentHandlerStr = "";
                var currentEventTypes = [];
                for each (var line in lines) {
                    if (line.match(lambdaRe)) {
                        // New Lambda function, process previous one if exists and reset handler structures
                        if (currentHandlerStr != "")
                            processHandler(currentHandlerStr, currentEventTypes);
                        currentHandlerStr = "";
                        currentEventTypes = [];
                    } else if (line.match(handlerRe)) {
                        // Process Handler declarations
                        currentHandlerStr = handlerRe.exec(line)[2].replace(/'/g, "").replace(/"/g, "");
                    } else if (line.match(eventTypeRe)) {
                        // Process Event type
                        currentEventTypes.push(eventTypeRe.exec(line)[2]);
                    }
                }
                if (currentHandlerStr != "")
                    processHandler(currentHandlerStr, currentEventTypes);
            }
        }
    } catch (err) {
        debugMsg("Error parsing AWS files");
        debugMsg(err)
    }
}

var xss_ct_sinks = [];
var xss_issues = [];
var xsscs_issues = [];
var vulns = getVulnerabilities();

for each (var vuln in vulns) {
    if (vuln === null || vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null) continue;

    var ruleId = String(vuln.getRule().getIdentifier());

    // Process XSS-enabling content-type sink
    if (
    // java sinks
    ruleId == "FDCFBA5C-0950-46DB-9EE4-D1B38C520A280"
     || ruleId == "608E6289-F91C-4613-96C1-5CD9CD2E1D640"
     // python sinks
     || ruleId == "24F7FE27-05CE-4CAB-A55A-6308BBB879FA0"
    ) {
        var xss_ct_sink = new Object();
        xss_ct_sink.primaryLine = vuln.getPrimaryLine();
        xss_ct_sink.primaryFile = vuln.getPrimaryFile();
        xss_ct_sinks.push(xss_ct_sink);
        vuln.remove();
    // Process XSS issues
    } else if (
            // java sinks
            ruleId == "63C7A9AF-5B44-4A46-8C21-E3C2639EF9700" // RequestHandler return statement
            || ruleId == "6E1F953A-5636-47C5-9388-137B0D55E94C"  // XSS:PV sink for write(Object)
            || ruleId == "76F7C5DF-850D-4AC8-A3FE-8AE7AABFB50E"  // XSS:PV sink for write(byte[],,)
            || ruleId == "D2CCABEC-2B85-4098-9DC4-ED47CA91D3AD"  // XSS:PV sink for write(char[],,)
            || ruleId == "13F1572D-8D31-468B-B578-D51F88401C0D"  // XSS:PV sink for write(char)
            || ruleId == "0E836836-C5D0-4977-9EC1-0CE2AFF9F083"  // XSS:PV sink for write(String,,)
            || ruleId == "60A5F5D9-5446-4DB0-B247-954D3F8C201F"  // XSS:PV sink for printf|format(String)
            || ruleId == "33A421F1-EE1A-467F-BE4A-EBFE352EE1D2"  // XSS:PV sink for printf|format(Locale,String)
            || ruleId == "F84BAB3E-8F3F-485D-91D3-6223E0832DBA"  // XSS:R sink for write(object)
            || ruleId == "F200F116-96DA-4F5B-A9AA-74EDBD984E84"  // XSS:R sink for write(byte[],,)
            || ruleId == "6EA1768A-744C-4638-8894-C6A1E07DAB14"  // XSS:R sink for write(char[],,)
            || ruleId == "B4E14469-A03F-49BA-B6C3-1907946C7E26"  // XSS:R sink for write(char)
            || ruleId == "798E4513-03B3-4252-A644-FBA596AEFB2B"  // XSS:R sink for write(String,,)
            || ruleId == "37C188AD-5F2D-4491-9721-3B89047BC707"  // XSS:R sink for printf|format(String)
            || ruleId == "CA606A4C-29F7-4CEB-82BF-CA1A05202050"  // XSS:R sink for printf|format(Locale,String)
            || ruleId == "71123E73-AC38-4B52-90DF-E4599DEE979F"  // XSS:ICC sink for write(object)
            || ruleId == "1996E9B9-2F85-4E5D-A343-01774EF4F548"  // XSS:ICC sink for write(byte[],,)
            || ruleId == "825CD973-4DB3-42A8-8DE4-6E9D9876711C"  // XSS:ICC sink for write(char[],,)
            || ruleId == "7CDEAFB1-D6C8-41D0-AD04-2040ECA9AE34"  // XSS:ICC sink for write(char)
            || ruleId == "C207FAA4-537A-497A-BDDB-C44763AC6FF4"  // XSS:ICC sink for write(String,,)
            || ruleId == "C55A9E30-A7C1-4D63-AF4B-73F06C5F55CF"  // XSS:ICC sink for printf|format(String)
            || ruleId == "D02426AF-9364-4C79-A3C8-3150FA42173A"  // XSS:ICC sink for printf|format(Local,String)
            || ruleId == "B90D58D3-DD4C-4E03-AFAD-0569434A8ED6"  // XSS:P sink for write(object)
            || ruleId == "5B9CE105-7C9E-402F-A6B5-3BB9EACDEE95"  // XSS:P sink for write(byte[],,)
            || ruleId == "93C25ADB-4075-4DAC-A3D6-F2B233E21C73"  // XSS:P sink for write(char[],,)
            || ruleId == "C4E88513-1AC2-4F65-8736-778D085B6020"  // XSS:P sink for write(char)
            || ruleId == "0BCF2BFC-1A1D-4156-8A58-FEFB307724AA"  // XSS:P sink for write(String,,)
            || ruleId == "1664DAA3-D3FA-439D-9724-B2A36EF993F7"  // XSS:P sink for printf|format(String,,)
            || ruleId == "008D06DB-8A45-425E-AA28-EED177A74D64"  // XSS:P sink for printf|format(Locale,String)
            // python sinks
            || ruleId == "5B063F30-8F58-4664-8082-E68E35F5979F0"  // XSS:R sink
            || ruleId == "4D3BCB46-4EFC-41D5-8788-FFF646D8EE8D0"  // XSS:P sink
            || ruleId == "30B92E58-6DCD-4508-AB2C-68073F029F0D0"  // XSS:PV sink
        ) {
        xss_issues.push(vuln);
    // Process XSS:CS issues
    } else if (ruleId == "78850E52-D2D7-47EE-9528-B1D6DBF0B5A80"  // RequestHandler return statement
            || ruleId == "395DBD7E-42AE-426D-8F16-F704D4C778CE"   // XSS:CS sinks for write(String,,)
            || ruleId == "7209708D-CB16-44F2-A521-24D756F92B5D"   // XSS:CS sinks for write(Object)
            || ruleId == "59A50C7C-7566-46AE-B05C-A91D658A6580"   // XSS:CS sinks for write(byte[],,)
            || ruleId == "5C0AE4D5-6229-4FCB-925F-9D3FBBE9F1A0"   // XSS:CS sinks for write(char[],,)
            || ruleId == "8DCAEA6D-B7AC-4951-81B2-DD13580249F6"   // XSS:CS sinks for write(char)
            || ruleId == "4DFDAE13-F02F-40FB-B8C1-7B925974C5AF"   // XSS:CS sinks for printf|format(String)
            || ruleId == "04565BF2-D483-4E5B-B59F-C4457350F5C6"   // XSS:CS sinks for printf|format(Locale,String)
            // python sinks
            || ruleId == "6AE30FBB-6217-4642-AFA9-302E82E5EDBB0"
        ) {
        xsscs_issues.push(vuln);
    }
}

// Remove XSSCS issues if there is a matching xss-enabling content-type
for each (var sink in xss_ct_sinks) {
    for each (var xss in xss_issues) {
        if (xss.getPrimaryLine() == sink.primaryLine && xss.getPrimaryFile() == sink.primaryFile) {
            for each (var xsscs in xsscs_issues) {
                if (xsscs.getPrimaryLine() == sink.primaryLine && xsscs.getPrimaryFile() == sink.primaryFile) {
                    //alert("Removing 1: " + sink.primaryFile + ":" +  sink.primaryLine )
                    xsscs.remove();
                }
            }
        }
    }
}
// Remove XSS issues if they dont have a matching xss-enabling content-type sink
for each (var xss in xss_issues) {
    //alert("Checking: " + xss.getPrimaryFile() + ":" +  xss.getPrimaryLine() )
    var encFunction = xss.getEnclosingFunction();
    if (encFunction == null || encFunction == undefined) continue;
    var remove = false;
    for each (var label in encFunction.getLabels()) {
        if (label == "AWS_Lambda_Handler") {
            remove = true;
            break;
        }
    }
    if (!remove) continue;
    for each (var sink in xss_ct_sinks) {
        if (xss.getPrimaryLine() == sink.primaryLine && xss.getPrimaryFile() == sink.primaryFile) {
            //alert("saving")
            remove = false;
        }
    }
    if (remove) {
        //alert("Removing 2: " + xss.getPrimaryFile() + ":" +  xss.getPrimaryLine() )
        xss.remove();
    }
}
